#[test]
fn a_brush_keeps_its_images_and_their_sizes() {
    let Some(s) = session(100, 100) else { return };
    let size = crate::studio::source_size() as usize;
    let sizes = vec!["max_size".to_owned()];
    // its own shape (sizes kept in that shape's unit), a shipped grain
    s.studio_begin();
    assert!(s.set_studio_source(crate::studio::SourceKind::Shape, vec![200; size * size]));
    assert!(s.set_studio_shipped_source(crate::studio::SourceKind::Grain, 2));
    s.set_studio_setting("max_size".to_owned(), 0.6);
    let grain = s.studio_source(crate::studio::SourceKind::Grain);
    s.studio_end(true);
    let Some(other) = session(100, 100) else { return };
    assert!(other.load_brush_library(s.saved_brush_library()));
    other.studio_begin();
    assert!((other.studio_settings(sizes.clone())[0] - 0.6).abs() < 1e-3);
    assert_eq!(other.studio_source(crate::studio::SourceKind::Shape), vec![200; size * size]);
    assert_eq!(other.studio_source(crate::studio::SourceKind::Grain), grain);
    other.studio_end(false);
    // a shipped shape in place of the round tip
    s.studio_begin();
    s.studio_reset();
    assert!(s.set_studio_shipped_source(crate::studio::SourceKind::Shape, 1));
    let shape = s.studio_source(crate::studio::SourceKind::Shape);
    s.studio_end(true);
    let Some(third) = session(100, 100) else { return };
    assert!(third.load_brush_library(s.saved_brush_library()));
    third.studio_begin();
    assert_eq!(third.studio_source(crate::studio::SourceKind::Shape), shape);
}

#[test]
fn a_brush_keeps_what_it_paints_materials_through() {
    use crate::studio::SourceKind::{Metallic, Roughness};
    let Some(s) = session(100, 100) else { return };
    let size = crate::studio::source_size() as usize;
    let amounts = || vec!["metallic_amount".to_owned(), "roughness_amount".to_owned(), "metallic_scale".to_owned()];
    s.studio_begin();
    // not metallic, half rough, each source tiled at a tenth, and neither an image (the amount all over)
    assert_eq!(s.studio_settings(amounts()), vec![0.0, 0.5, 0.1]);
    assert!(s.studio_source(Metallic).is_empty() && s.studio_source(Roughness).is_empty());
    assert!(s.set_studio_source(Metallic, vec![90; size * size]));
    assert!(s.set_studio_shipped_source(Roughness, 3));
    s.set_studio_setting("metallic_amount".to_owned(), 0.7);
    let rough = s.studio_source(Roughness);
    assert_eq!(rough.len(), size * size);
    s.studio_end(true);
    // kept with the library
    let Some(other) = session(100, 100) else { return };
    assert!(other.load_brush_library(s.saved_brush_library()));
    other.studio_begin();
    assert_eq!(other.studio_source(Metallic), vec![90; size * size]);
    assert_eq!(other.studio_source(Roughness), rough);
    assert!((other.studio_settings(amounts())[0] - 0.7).abs() < 1e-3);
    other.studio_end(false);
    // and with a brush file: both images its own, the amount as it was
    let b = s.current_brush();
    let set = other.import_brushes(s.brush_as_file(b.set, b.index).unwrap()).unwrap();
    assert!(other.select_brush(set, 0));
    other.studio_begin();
    assert_eq!(other.studio_source(Metallic), vec![90; size * size]);
    assert_eq!(other.studio_source(Roughness), rough);
    assert!((other.studio_settings(amounts())[0] - 0.7).abs() < 1e-3);
}

#[test]
fn a_studio_slider_has_its_own_pressure_curve_and_tilt() {
    let s = CanvasSession::new(64, 64);
    s.studio_begin();
    // which sliders offer what
    let scatter = crate::studio::slider_extras("scatter".into());
    assert!(scatter.pressure && !scatter.tilt);
    let count = crate::studio::slider_extras("count".into());
    assert!(count.pressure && count.tilt && count.tilt_switch == "count_tilt");
    let gradation = crate::studio::slider_extras("tilt_gradation".into());
    assert!(!gradation.pressure && gradation.tilt && gradation.tilt_switch.is_empty());
    // a curve given, read back, and taken away
    assert!(s.studio_slider_curve("scatter".into()).is_empty());
    s.set_studio_slider_curve("scatter".into(), vec![0.0, 0.0, 0.5, 0.8, 1.0, 1.0]);
    assert_eq!(s.studio_slider_curve("scatter".into()), vec![0.0, 0.0, 0.5, 0.8, 1.0, 1.0]);
    s.set_studio_slider_curve("scatter".into(), Vec::new());
    assert!(s.studio_slider_curve("scatter".into()).is_empty());
    // the size's own response: straight reads as off
    s.set_studio_slider_curve("pressure_size".into(), vec![0.0, 0.0, 0.5, 0.2, 1.0, 1.0]);
    assert_eq!(s.studio_slider_curve("pressure_size".into()).len(), 6);
    s.set_studio_slider_curve("pressure_size".into(), Vec::new());
    assert!(s.studio_slider_curve("pressure_size".into()).is_empty());
    // a slider without a curve keeps none
    s.set_studio_slider_curve("spacing".into(), vec![0.0, 0.0, 1.0, 1.0]);
    assert!(s.studio_slider_curve("spacing".into()).is_empty());
}

#[test]
fn the_brush_studio_edits_keeps_and_puts_back() {
    let Some(s) = session(100, 100) else { return };
    let name = s.studio_begin();
    assert!(!name.is_empty());
    let keys = vec!["spacing".to_owned(), "wet_pull".to_owned()];
    let start = s.studio_settings(keys.clone());
    s.set_studio_setting("spacing".to_owned(), 0.5);
    s.set_studio_setting("wet_pull".to_owned(), 0.2);
    assert_eq!(s.studio_settings(keys.clone()), vec![0.5, 0.2]);
    s.set_studio_curve(vec![0.0, 0.0, 0.5, 0.2, 1.0, 1.0]);
    assert_eq!(s.studio_curve().len(), 6);
    // cancelled, it opens as it was
    s.studio_end(false);
    s.studio_begin();
    assert_eq!(s.studio_settings(keys.clone()), start);
    assert_eq!(s.studio_curve().len(), 4);
    // kept, it stays; reset, it is as it ships
    s.set_studio_setting("spacing".to_owned(), 0.5);
    s.studio_end(true);
    s.studio_begin();
    assert_eq!(s.studio_settings(keys.clone())[0], 0.5);
    s.studio_reset();
    assert_eq!(s.studio_settings(keys.clone()), start);
    s.studio_end(true);
    // a stroke still draws with the edited brush
    s.stroke_begin(PointerKind::Finger, vec![sample(50.0, 50.0, 0.0)]);
    s.stroke_end(vec![]);
    // changes carry to another session
    s.studio_begin();
    s.set_studio_setting("spacing".to_owned(), 0.33);
    s.set_studio_setting("wet_attack".to_owned(), 0.25);
    s.studio_end(true);
    let kept = s.saved_brush_library();
    let Some(other) = session(100, 100) else { return };
    assert!(other.load_brush_library(kept));
    other.studio_begin();
    assert_eq!(other.studio_settings(vec!["spacing".to_owned(), "wet_attack".to_owned()]), vec![0.33, 0.25]);
    other.studio_end(false);
    other.apply_brush_changes("not json".to_owned());
    assert!(!other.load_brush_library("not json".to_owned()));
    // a pad paints like it, in its own colour, at the preview size
    let Some(pad) = session(100, 100) else { return };
    s.studio_begin();
    s.set_studio_setting("preview_size".to_owned(), 0.5);
    pad.paint_like(s.clone(), 1.0, 0.0, 0.0);
    pad.stroke_begin(PointerKind::Finger, vec![sample(50.0, 50.0, 0.0)]);
    pad.stroke_end(vec![]);
    assert_eq!(pixel(&pad, 50, 50), [255, 0, 0, 255]);
    s.studio_end(false);
}

#[test]
fn a_held_stroke_snaps_to_its_line_as_stabilisation_smoothed_it_but_not_streamline() {
    use crate::quickshape::QuickShapeKind;
    // a line across with a 12 px wobble, 6 times along it: too wavy for a line as it came
    let pts: Vec<PenSample> = (0..=75)
        .map(|i| {
            let x = 25.0 + i as f32 * 2.0;
            sample(x, 100.0 + 12.0 * (i as f32 / 75.0 * 6.0 * std::f32::consts::TAU).sin(), f64::from(i) * 8.0)
        })
        .collect();
    let held = |setting: &str, amount: f32| {
        let s = session(200, 200)?;
        s.set_brush_size(0.05);
        s.studio_begin();
        s.set_studio_setting("streamline".to_owned(), 0.0);
        s.set_studio_setting(setting.to_owned(), amount);
        s.studio_end(true);
        s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
        s.stroke_add(pts[1..].to_vec());
        s.quickshape_hold().map(|info| info.kind)
    };
    let Some(raw) = held("stabilization", 0.0) else { return };
    assert_ne!(raw, QuickShapeKind::Line);
    // a heavy streamline is left out of the line a shape is fitted to
    assert_eq!(held("streamline", 1.0), Some(raw));
    // stabilisation evens the wobble out of it
    assert_eq!(held("stabilization", 1.0), Some(QuickShapeKind::Line));
}

#[test]
fn a_held_stroke_snaps_to_a_shape_and_is_edited() {
    use crate::quickshape::QuickShapeKind;
    let Some(s) = session(200, 200) else { return };
    s.set_brush_size(0.2);
    // a rough circle, held
    let pts: Vec<PenSample> = (0..=60)
        .map(|i| {
            let t = i as f32 / 60.0 * std::f32::consts::TAU;
            sample(100.0 + 60.0 * t.cos() + 2.0 * (7.0 * t).sin(), 100.0 + 40.0 * t.sin(), f64::from(i) * 8.0)
        })
        .collect();
    s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
    s.stroke_add(pts[1..].to_vec());
    let info = s.quickshape_hold().expect("a shape");
    assert_eq!(info.kind, QuickShapeKind::Ellipse);
    assert_eq!(info.handles.len(), 8);
    s.stroke_end(vec![]);
    // still open, and undo is there for it
    assert!(s.info().can_undo);
    // shown as a circle, then a handle dragged
    let circle = s.quickshape_choose(QuickShapeKind::Circle).unwrap();
    assert_eq!(circle.kind, QuickShapeKind::Circle);
    let moved = s.quickshape_move_handle(0, 190.0, 100.0).unwrap();
    assert!((moved.handles[0] - 190.0).abs() < 1.0, "{:?}", moved.handles);
    s.quickshape_done();
    assert!(s.quickshape_info().is_none());
    // the circle's edge is painted, its middle is not
    assert_eq!(pixel(&s, 10, 100)[0], 0);
    assert_eq!(pixel(&s, 100, 100), [255, 255, 255, 255]);
    s.undo();
    assert_eq!(pixel(&s, 10, 100), [255, 255, 255, 255]);
    // a scribble too short to be anything does not snap
    s.stroke_begin(PointerKind::Finger, vec![sample(10.0, 10.0, 0.0)]);
    assert!(s.quickshape_hold().is_none());
    s.stroke_end(vec![]);
}

/// The layer's alpha as the last render left it: how many pixels hold paint (past a few levels)
/// and how much ink there is in all (alpha summed, 0..1 a pixel).
fn layer_ink(s: &CanvasSession) -> (usize, f64) {
    let mut guard = s.shared.lock();
    let st = &mut *guard;
    let id = st.doc.current();
    let (canvas, gpu) = (st.canvas.as_mut().unwrap(), st.gpu.as_ref().unwrap());
    canvas.render_finished(gpu, &mut st.doc);
    let px = canvas.read_layer(gpu, id).unwrap();
    let alphas = px.chunks(4).map(|p| p[3]);
    (alphas.clone().filter(|&a| a > 8).count(), alphas.map(|a| f64::from(a) / 255.0).sum())
}

#[test]
fn a_dual_brush_s_shape_is_drawn_with_its_second_as_its_stroke_is() {
    use crate::quickshape::QuickShapeKind;
    use procraft_engine::brush::Brush;
    let Some(s) = session(200, 200) else { return };
    s.set_brush_size(0.3);
    s.set_color(0.0, 0.0, 0.0);
    // a line across, drawn as it is or held until it snaps to a line (the same line), its ink
    let pts: Vec<PenSample> = (0..=40).map(|i| sample(20.0 + i as f32 * 4.0, 100.0, f64::from(i) * 8.0)).collect();
    let line = |s: &CanvasSession, held: bool| {
        s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
        s.stroke_add(pts[1..].to_vec());
        if held {
            assert_eq!(s.quickshape_hold().map(|i| i.kind), Some(QuickShapeKind::Line));
        }
        s.stroke_end(vec![]);
        if held {
            s.quickshape_done();
        }
        let ink = layer_ink(s);
        s.undo();
        ink
    };
    let first_alone = line(&s, false);
    // its second: wide dabs far apart, multiplied with the first, so the stroke shows only where
    // both are: wet or dry, the shape is cut by it as the stroke drawn is (it was its first alone)
    let mut second = Brush { name: "Dabs".to_owned(), ..Brush::round_pen() };
    second.set_setting("spacing", 1.0);
    for wet in [false, true] {
        {
            let mut guard = s.shared.lock();
            let st = &mut *guard;
            let tool = st.tool;
            let brush = st.brush_mut(tool).unwrap();
            brush.secondary = Some(Box::new(second.clone()));
            brush.set_setting("dual_blend", 1.0);
            if wet {
                brush.set_setting("wet_dilution", 0.5);
                brush.set_setting("wet_charge", 1.0);
                assert!(brush.mixes_wet());
            }
        }
        let drawn = line(&s, false);
        let snapped = line(&s, true);
        eprintln!("wet {wet}: first alone {first_alone:?}, drawn {drawn:?}, snapped {snapped:?}");
        assert!(drawn.0 < first_alone.0 * 3 / 4, "the second cuts the stroke drawn: {drawn:?} of {first_alone:?}");
        let pixels = snapped.0 as f64 / drawn.0 as f64;
        let ink = snapped.1 / drawn.1;
        assert!((0.9..1.1).contains(&pixels) && (0.9..1.1).contains(&ink), "wet {wet}: {snapped:?} against {drawn:?}");
        // and given way to again, the stroke as it was drawn, its second too
        s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
        s.stroke_add(pts[1..].to_vec());
        s.quickshape_hold().unwrap();
        s.stroke_end(vec![]);
        s.quickshape_done();
        assert!(s.quickshape_undo(), "the shape gives way to its stroke");
        let back = layer_ink(&s);
        assert!((back.0 as f64 / drawn.0 as f64 - 1.0).abs() < 0.1, "wet {wet}: back {back:?} against {drawn:?}");
        s.undo();
    }
}

#[test]
fn a_shape_is_drawn_through_the_app_s_pressure_curve_as_its_stroke_was() {
    use crate::quickshape::QuickShapeKind;
    let Some(s) = session(200, 200) else { return };
    s.set_brush_size(0.3);
    s.set_color(0.0, 0.0, 0.0);
    // a pen pressing half way, through an app pressure curve that takes that up to nine tenths, and
    // a brush whose opacity follows the pressure
    s.shared.lock().input.pressure_curve = procraft_engine::curve::Curve::new(&[
        procraft_engine::geom::Vec2::new(0.0, 0.0),
        procraft_engine::geom::Vec2::new(0.5, 0.9),
        procraft_engine::geom::Vec2::new(1.0, 1.0),
    ]);
    {
        let mut guard = s.shared.lock();
        let st = &mut *guard;
        let tool = st.tool;
        st.brush_mut(tool).unwrap().set_setting("pressure_opacity", 1.0);
    }
    let pts: Vec<PenSample> = (0..=40)
        .map(|i| PenSample { pressure: 0.5, ..sample(20.0 + i as f32 * 4.0, 100.0, f64::from(i) * 8.0) })
        .collect();
    let line = |held: bool| {
        s.stroke_begin(PointerKind::Stylus, pts[..1].to_vec());
        s.stroke_add(pts[1..].to_vec());
        if held {
            assert_eq!(s.quickshape_hold().map(|i| i.kind), Some(QuickShapeKind::Line));
        }
        s.stroke_end(vec![]);
        if held {
            s.quickshape_done();
        }
        let ink = layer_ink(&s);
        s.undo();
        ink
    };
    let (drawn, snapped) = (line(false), line(true));
    eprintln!("drawn {drawn:?}, snapped {snapped:?}");
    // (the curve's own pressure, not the pen's: drawn without it the line came out far fainter)
    assert!((snapped.1 / drawn.1 - 1.0).abs() < 0.1, "{snapped:?} against {drawn:?}");
}

#[test]
fn a_long_wet_stroke_made_a_shape_is_laid_quickly_and_never_breaks() {
    use procraft_engine::brush::Brush;
    let Some(s) = session(1024, 1024) else { return };
    s.set_brush_size(0.5);
    s.set_color(0.1, 0.2, 0.8);
    {
        let mut guard = s.shared.lock();
        let st = &mut *guard;
        let tool = st.tool;
        let brush = st.brush_mut(tool).unwrap();
        brush.set_setting("wet_dilution", 0.6);
        brush.set_setting("wet_charge", 0.5);
        brush.set_setting("wet_pull", 0.5);
        brush.secondary = Some(Box::new(Brush { name: "Second".to_owned(), ..Brush::round_pen() }));
        brush.set_setting("dual_blend", 1.0);
    }
    let finish = |s: &CanvasSession| {
        let mut guard = s.shared.lock();
        let st = &mut *guard;
        let (canvas, gpu) = (st.canvas.as_mut().unwrap(), st.gpu.as_ref().unwrap());
        canvas.render_finished(gpu, &mut st.doc);
        assert_eq!(gpu.errors(), 0, "GPU validation errors");
    };
    // a long line, an ellipse and a zigzag, each held until it snaps, then moved about
    let line: Vec<(f32, f32)> = (0..=200).map(|i| (60.0 + i as f32 * 4.5, 500.0)).collect();
    let round: Vec<(f32, f32)> = (0..=200)
        .map(|i| {
            let t = i as f32 / 200.0 * std::f32::consts::TAU;
            (512.0 + 380.0 * t.cos(), 512.0 + 260.0 * t.sin())
        })
        .collect();
    let zigzag: Vec<(f32, f32)> = (0..=200)
        .map(|i| {
            (
                60.0 + i as f32 * 4.5,
                400.0 + if (i / 50) % 2 == 0 { (i % 50) as f32 * 6.0 } else { 300.0 - (i % 50) as f32 * 6.0 },
            )
        })
        .collect();
    for (name, path) in [("line", line), ("ellipse", round), ("polyline", zigzag)] {
        let pts: Vec<PenSample> = path.iter().enumerate().map(|(i, &(x, y))| sample(x, y, i as f64 * 8.0)).collect();
        let began = std::time::Instant::now();
        s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
        for some in pts[1..].chunks(4) {
            s.stroke_add(some.to_vec());
            finish(&s);
        }
        let drawn_ms = began.elapsed().as_secs_f64() * 1000.0 / (pts.len() as f64 / 4.0);
        let snap = std::time::Instant::now();
        let Some(info) = s.quickshape_hold() else { panic!("{name}: no shape") };
        finish(&s);
        let snap_ms = snap.elapsed().as_secs_f64() * 1000.0;
        s.stroke_end(vec![]);
        // dragged about: each move redrawn by the next frame
        let mut moves = Vec::new();
        for k in 0..6 {
            let t = std::time::Instant::now();
            s.quickshape_move(400.0, 400.0, 400.0 + k as f32 * 3.0, 400.0 + k as f32 * 2.0);
            s.shared.lock().draw_moved_shape();
            finish(&s);
            moves.push(t.elapsed().as_secs_f64() * 1000.0);
        }
        // and a handle dragged onto another: a shape of no size, which draws a dot or nothing
        let (hx, hy) = (info.handles[0], info.handles[1]);
        for k in 1..info.handles.len() / 2 {
            s.quickshape_move_handle(k as u32, hx, hy);
            s.shared.lock().draw_moved_shape();
            finish(&s);
        }
        s.quickshape_done();
        finish(&s);
        let worst = moves.iter().copied().fold(0.0, f64::max);
        eprintln!(
            "{name} ({:?}): a frame of drawing {drawn_ms:.1} ms, the snap {snap_ms:.1} ms, a move at most {worst:.1} ms",
            info.kind
        );
        s.undo();
    }
}

#[test]
fn an_edited_shape_is_turned_by_its_outline_and_moved_elsewhere() {
    use crate::quickshape::QuickShapeKind;
    let Some(s) = session(200, 200) else { return };
    s.set_brush_size(0.2);
    let pts: Vec<PenSample> = (0..=60)
        .map(|i| {
            let t = i as f32 / 60.0 * std::f32::consts::TAU;
            sample(100.0 + 60.0 * t.cos(), 100.0 + 40.0 * t.sin(), f64::from(i) * 8.0)
        })
        .collect();
    s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
    s.stroke_add(pts[1..].to_vec());
    assert_eq!(s.quickshape_hold().unwrap().kind, QuickShapeKind::Ellipse);
    s.stroke_end(vec![]);
    let before = s.quickshape_info().unwrap();
    // on its outline (the first axis end), not in its middle
    let (ex, ey) = (before.handles[0], before.handles[1]);
    assert!(s.quickshape_near_edge(ex, ey - 5.0, 22.0));
    assert!(!s.quickshape_near_edge(100.0, 100.0, 22.0));
    // the outline dragged half as far out again: half as big again about its centre
    s.quickshape_pin(ex, ey, true);
    let grown = s.quickshape_pin(100.0 + (ex - 100.0) * 1.5, 100.0 + (ey - 100.0) * 1.5, false).unwrap();
    assert!((grown.handles[0] - (100.0 + (ex - 100.0) * 1.5)).abs() < 1.0, "{:?}", grown.handles);
    s.quickshape_unpin();
    // dragged elsewhere: it moves along
    let moved = s.quickshape_move(100.0, 100.0, 110.0, 95.0).unwrap();
    for (i, (a, b)) in grown.handles.iter().zip(&moved.handles).enumerate() {
        let d = if i % 2 == 0 { 10.0 } else { -5.0 };
        assert!((b - a - d).abs() < 0.5, "{i}: {a} -> {b}");
    }
    s.quickshape_done();
}

#[test]
fn a_shape_dragged_about_ends_as_one_moved_there_at_once() {
    use procraft_gpu::wgpu;
    // wet paint laid in place (the heaviest to draw again) and a plain round brush
    for wanted in ["Elfin Saddle", "Hard Airbrush"] {
        // the canvas as dragged by `moves` (window pixels, the canvas shown at its size), frames
        // drawn after those marked, then kept
        let kept = |moves: &[(f32, f32, bool)]| -> Option<Vec<u8>> {
            let s = session(200, 200)?;
            let library = s.brush_library();
            let (set, index) = library
                .iter()
                .enumerate()
                .find_map(|(i, set)| set.brushes.iter().position(|b| b.name == wanted).map(|j| (i as u32, j as u32)))?;
            s.select_brush(set, index);
            s.set_brush_size(0.3);
            let target = s.shared.lock().gpu.as_ref()?.device.create_texture(&wgpu::TextureDescriptor {
                label: Some("window"),
                size: wgpu::Extent3d { width: 200, height: 200, depth_or_array_layers: 1 },
                mip_level_count: 1,
                sample_count: 1,
                dimension: wgpu::TextureDimension::D2,
                format: wgpu::TextureFormat::Rgba8Unorm,
                usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
                view_formats: &[],
            });
            let view = target.create_view(&Default::default());
            let started = std::time::Instant::now();
            let frame = || {
                let format = wgpu::TextureFormat::Rgba8Unorm;
                let srgb = procraft_engine::profile::Profile::Srgb;
                s.shared.lock().draw_frame(&view, format, (200, 200), srgb, started);
            };
            let oval: Vec<PenSample> = (0..=60)
                .map(|i| {
                    let t = i as f32 / 60.0 * std::f32::consts::TAU;
                    sample(90.0 + 50.0 * t.cos(), 90.0 + 30.0 * t.sin(), f64::from(i) * 8.0)
                })
                .collect();
            s.stroke_begin(PointerKind::Stylus, oval[..1].to_vec());
            s.stroke_add(oval[1..].to_vec());
            s.quickshape_hold()?;
            s.stroke_end(vec![]);
            frame();
            let mut at = (90.0, 90.0);
            for &(dx, dy, then_frame) in moves {
                s.quickshape_move(at.0, at.1, at.0 + dx, at.1 + dy);
                at = (at.0 + dx, at.1 + dy);
                if then_frame {
                    frame();
                }
            }
            s.quickshape_done();
            pixel(&s, 0, 0);
            let mut guard = s.shared.lock();
            let st = &mut *guard;
            st.canvas.as_mut()?.read_composite(st.gpu.as_ref()?).ok()
        };
        // several moves a frame, then more after the last frame
        let dragged = [false, true, false, false, true, false].map(|then_frame| (3.0, 2.0, then_frame));
        let Some(about) = kept(&dragged) else { return };
        let Some(at_once) = kept(&[(18.0, 12.0, true)]) else { return };
        assert!(about.iter().zip(&at_once).all(|(a, b)| a == b), "{wanted}: the pixels differ");
        assert_eq!(about.len(), at_once.len());
    }
}

#[test]
fn a_shape_still_held_follows_the_pen_and_a_finger_snaps_it() {
    use crate::quickshape::QuickShapeKind;
    let Some(s) = session(200, 200) else { return };
    s.set_brush_size(0.2);
    let angle = |i: &crate::quickshape::QuickShapeInfo| {
        (i.handles[3] - i.handles[1]).atan2(i.handles[2] - i.handles[0]).to_degrees()
    };
    // a line, held at its end
    let pts: Vec<PenSample> = (0..=40).map(|i| sample(20.0 + i as f32 * 2.0, 100.0, f64::from(i) * 8.0)).collect();
    s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
    s.stroke_add(pts[1..].to_vec());
    let info = s.quickshape_hold().expect("a shape");
    assert_eq!(info.kind, QuickShapeKind::Line);
    // the pen moves on: the line's end goes with it, turning about its start
    s.stroke_add(vec![sample(80.0, 160.0, 400.0)]);
    let moved = s.quickshape_info().unwrap();
    assert!((moved.handles[2] - 80.0).abs() < 1.0 && (moved.handles[3] - 160.0).abs() < 1.0, "{:?}", moved.handles);
    assert!((moved.handles[0] - 20.0).abs() < 1.0 && (moved.handles[1] - 100.0).abs() < 1.0);
    // a finger down: the angle in 15 degree steps (45 already is one)
    assert!((angle(&s.quickshape_finger(true).unwrap()) - 45.0).abs() < 0.5);
    s.stroke_add(vec![sample(150.0, 130.0, 450.0)]);
    assert!((angle(&s.quickshape_info().unwrap()) - 15.0).abs() < 0.5);
    // lifted: back to following the pen freely (about 13 degrees)
    let free = s.quickshape_finger(false).unwrap();
    assert!((free.handles[2] - 150.0).abs() < 1.0 && (free.handles[3] - 130.0).abs() < 1.0, "{:?}", free.handles);
    // down again, and the pen lifts first: the stepped line is kept
    let on = s.quickshape_finger(true).unwrap();
    assert!((angle(&on) - 15.0).abs() < 0.5);
    s.stroke_end(vec![]);
    // let go, it stays put, fingers or not
    s.stroke_add(vec![sample(30.0, 30.0, 500.0)]);
    assert_eq!(s.quickshape_info().unwrap().handles, on.handles);
    assert_eq!(s.quickshape_finger(false).unwrap().handles, on.handles);
    s.quickshape_done();
    // a held ellipse near round is a circle while a finger is down
    let pts: Vec<PenSample> = (0..=60)
        .map(|i| {
            let t = i as f32 / 60.0 * std::f32::consts::TAU;
            sample(100.0 + 60.0 * t.cos() + 2.0 * (7.0 * t).sin(), 100.0 + 40.0 * t.sin(), f64::from(i) * 8.0)
        })
        .collect();
    s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
    s.stroke_add(pts[1..].to_vec());
    assert_eq!(s.quickshape_hold().unwrap().kind, QuickShapeKind::Ellipse);
    assert_eq!(s.quickshape_finger(true).unwrap().kind, QuickShapeKind::Circle);
    assert_eq!(s.quickshape_finger(false).unwrap().kind, QuickShapeKind::Ellipse);
    assert_eq!(s.quickshape_finger(true).unwrap().kind, QuickShapeKind::Circle);
    s.stroke_end(vec![]);
    assert_eq!(s.quickshape_info().unwrap().kind, QuickShapeKind::Circle);
    s.quickshape_done();
}

#[test]
fn undo_goes_back_through_a_shapes_drags_to_the_stroke_it_was_made_of() {
    use crate::quickshape::QuickShapeKind;
    let Some(s) = session(200, 200) else { return };
    s.set_brush_size(0.02);
    // a wavering line, a line once it snaps
    let pts: Vec<PenSample> = (0..=40)
        .map(|i| {
            let t = i as f32 / 40.0;
            sample(20.0 + 160.0 * t, 100.0 + 5.0 * (t * 18.0).sin(), f64::from(i) * 8.0)
        })
        .collect();
    let draw = || {
        s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
        s.stroke_add(pts[1..].to_vec());
    };
    // (as drawn, an open shape staying open)
    let seen = || {
        let mut guard = s.shared.lock();
        let st = &mut *guard;
        let (canvas, gpu) = (st.canvas.as_mut().unwrap(), st.gpu.as_ref().unwrap());
        canvas.render(gpu, &mut st.doc, None);
        canvas.read_composite(gpu).unwrap()
    };
    let blank = seen();
    draw();
    s.stroke_end(vec![]);
    let stroke = seen();
    s.undo();
    assert_eq!(seen(), blank);
    draw();
    let info = s.quickshape_hold().expect("a shape");
    assert_eq!(info.kind, QuickShapeKind::Line);
    s.stroke_end(vec![]);
    let snapped = seen();
    assert_ne!(snapped, stroke);
    // a drag is a step of its own, back and forward, the shape staying open
    s.quickshape_step();
    let moved = s.quickshape_move_handle(1, 180.0, 60.0).unwrap();
    assert!(!s.info().can_redo);
    s.undo();
    assert_eq!(s.quickshape_info().unwrap().handles, info.handles);
    assert_eq!(seen(), snapped);
    assert!(s.info().can_redo);
    s.redo();
    assert_eq!(s.quickshape_info().unwrap().handles, moved.handles);
    assert!(!s.info().can_redo);
    s.undo();
    // past the drags the shape goes, its stroke back as drawn
    s.undo();
    assert!(s.quickshape_info().is_none());
    assert_eq!(seen(), stroke);
    assert!(s.info().can_undo && s.info().can_redo);
    // redone, it is the shape as it snapped, kept, its drags gone
    s.redo();
    assert!(s.quickshape_info().is_none());
    assert_eq!(seen(), snapped);
    assert!(!s.info().can_redo);
    // and so on either way, a kept shape as one being edited
    s.undo();
    assert_eq!(seen(), stroke);
    s.undo();
    assert_eq!(seen(), blank);
    s.redo();
    assert_eq!(seen(), stroke);
    s.redo();
    assert_eq!(seen(), snapped);
    // with something done since, undo takes that, and the shape is a step like any other
    s.stroke_begin(PointerKind::Finger, vec![sample(30.0, 30.0, 900.0)]);
    s.stroke_end(vec![]);
    s.undo();
    assert_eq!(seen(), snapped);
    s.undo();
    assert_eq!(seen(), blank);
}

#[test]
fn a_nodes_drag_by_touch_is_one_step_of_undo_and_a_tap_on_it_none() {
    let Some(s) = session(200, 200) else { return };
    s.set_brush_size(0.02);
    let pts: Vec<PenSample> = (0..=40).map(|i| sample(20.0 + 4.0 * i as f32, 100.0, f64::from(i) * 8.0)).collect();
    s.stroke_begin(PointerKind::Finger, pts[..1].to_vec());
    s.stroke_add(pts[1..].to_vec());
    let info = s.quickshape_hold().expect("a shape");
    s.stroke_end(vec![]);
    s.set_shape_editing(true);
    let (x, y) = (info.handles[2], info.handles[3]);
    let drag = |by: f32, from: f64| {
        s.touch_down(7, PointerKind::Finger, vec![sample(x, y, from)]);
        for i in 1..=5 {
            let (i, t) = (i as f32, f64::from(i) * 16.0);
            s.touch_move(7, vec![sample(x, y + by * i / 5.0, from + t)]);
        }
        s.touch_up(7, vec![]);
    };
    s.touch_down(7, PointerKind::Finger, vec![sample(x, y, 1900.0)]);
    s.touch_up(7, vec![]);
    drag(40.0, 2000.0);
    let moved = s.quickshape_info().unwrap();
    // it stayed for the first ten points of the way (two pixels each here), then went as the
    // finger did, behind it
    let lag = 40.0 - (moved.handles[3] - info.handles[3]);
    assert!((20.0..=28.0).contains(&lag), "{lag}");
    assert!((moved.handles[2] - info.handles[2]).abs() < 1.0, "{:?}", moved.handles);
    // five moves, one step: one undo has it all back, the shape still open
    s.undo();
    assert_eq!(s.quickshape_info().unwrap().handles, info.handles);
    s.redo();
    assert_eq!(s.quickshape_info().unwrap().handles, moved.handles);
    s.undo();
    // past it the shape goes: the tap made no step of its own
    s.undo();
    assert!(s.quickshape_info().is_none());
}

#[test]
fn a_mask_takes_what_is_pasted_by_its_brightness_only_when_asked() {
    let Some(s) = session(64, 64) else { return };
    s.set_color(1.0, 0.0, 0.0);
    let layer = s.layers().iter().find(|l| l.current).unwrap().id;
    assert!(s.fill_layer(layer));
    let mask = s.add_mask(layer).unwrap();
    s.select_layer(mask);
    // white on the left, clear on the right: a sketch on a layer of its own
    let rgba: Vec<u8> = (0..64 * 64).flat_map(|i| if i % 64 < 32 { [255; 4] } else { [0; 4] }).collect();
    let picture = crate::layers::ThumbnailImage { width: 64, height: 64, rgba };
    // as anything pasted, a new layer
    let layers = s.layers().len();
    let pasted = s.paste(picture.clone()).unwrap();
    assert_eq!(s.layers().len(), layers + 1);
    assert_ne!(pasted, mask);
    s.undo();
    assert_eq!(s.layers().len(), layers);
    s.select_layer(mask);
    // asked to, the mask holds it: the layer shows where it was bright, nowhere else
    let (_plugins, plugin_files) = crate::hooks::tests::paste_into_masks(&s, "mask-takes-paste");
    assert_eq!(s.paste(picture.clone()), Some(mask));
    assert_eq!(s.layers().len(), layers);
    assert_eq!(pixel(&s, 10, 32), [255, 0, 0, 255]);
    assert_eq!(pixel(&s, 50, 32), [255, 255, 255, 255]);
    // one step back to the mask as it was
    s.undo();
    assert_eq!(pixel(&s, 50, 32), [255, 0, 0, 255]);
    // from another app too: smaller than the canvas, in the middle of it, the rest hidden
    let square = crate::layers::ThumbnailImage { width: 16, height: 16, rgba: vec![255; 16 * 16 * 4] };
    assert!(s.paste_picture_into_mask(square.clone()));
    assert_eq!(s.layers().len(), layers);
    assert_eq!(pixel(&s, 32, 32), [255, 0, 0, 255]);
    assert_eq!(pixel(&s, 4, 4), [255, 255, 255, 255]);
    s.undo();
    // on any other layer it is a new layer still
    s.select_layer(layer);
    assert!(!s.paste_picture_into_mask(square));
    assert_ne!(s.paste(picture), Some(layer));
    assert_eq!(s.layers().len(), layers + 1);
    let _ = std::fs::remove_dir_all(plugin_files);
}

#[test]
fn copy_cut_paste_and_flip() {
    let Some(s) = session(100, 100) else { return };
    s.set_brush_size(0.4);
    s.set_color(1.0, 0.0, 0.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(20.0, 50.0, 0.0)]);
    s.stroke_end(vec![]);
    let copied = s.copy_layer().unwrap();
    let layers = s.layers().len();
    let pasted = s.paste(copied.clone()).unwrap();
    assert_eq!(s.layers().len(), layers + 1);
    assert_eq!(s.layers().iter().find(|l| l.current).map(|l| l.id), Some(pasted));
    // flipped left to right, both layers' red is now on the right, as one undo step
    s.flip_canvas(true);
    assert_eq!(pixel(&s, 79, 50), [255, 0, 0, 255]);
    assert_eq!(pixel(&s, 20, 50), [255, 255, 255, 255]);
    s.undo();
    assert_eq!(pixel(&s, 20, 50), [255, 0, 0, 255]);
    // cut takes it off the layer
    let cut = s.cut_layer().unwrap();
    assert_eq!(cut.rgba, copied.rgba);
    s.delete_layer(pasted);
    s.cut_layer().unwrap();
    assert_eq!(pixel(&s, 20, 50), [255, 255, 255, 255]);
    // a photo comes in as straight colour, premultiplied
    let photo = crate::layers::ThumbnailImage { width: 2, height: 2, rgba: [255, 0, 0, 128].repeat(4) };
    assert!(s.insert_image(photo, false).is_some());
    let canvas = s.copy_canvas().unwrap();
    assert_eq!(canvas.rgba.len(), 100 * 100 * 4);
}

#[test]
fn an_adjustment_leaves_an_alpha_locked_layer_s_alpha_as_it_is() {
    use crate::adjust::SwipeAdjustment;
    let Some(s) = session(100, 100) else { return };
    // red beside blue, with clear all round
    let mut rgba = vec![0u8; 100 * 100 * 4];
    for y in 20..80 {
        for x in 20..80 {
            rgba[(y * 100 + x) * 4..][..4].copy_from_slice(if x < 50 { &[255, 0, 0, 255] } else { &[0, 0, 255, 255] });
        }
    }
    let id = s.paste(crate::layers::ThumbnailImage { width: 100, height: 100, rgba }).unwrap();
    let alpha = |s: &CanvasSession| -> Vec<u8> {
        s.copy_layer_contents(id).unwrap().rgba.as_chunks::<4>().0.iter().map(|p| p[3]).collect()
    };
    let before = alpha(&s);
    let blur = |s: &CanvasSession| {
        assert!(s.adjust_begin());
        s.adjust_swipe(SwipeAdjustment::GaussianBlur, 0.5);
        s.adjust_end(true);
    };
    assert!(s.set_layer_alpha_lock(id, true));
    blur(&s);
    assert!(alpha(&s) == before, "the blur stayed inside what was painted");
    let at = |s: &CanvasSession, x: usize| {
        <[u8; 4]>::try_from(&s.copy_layer_contents(id).unwrap().rgba[(50 * 100 + x) * 4..][..4]).unwrap()
    };
    // it did blur: where the colours meet they mix, at full cover
    let [r, _, b, a] = at(&s, 50);
    assert!(r > 40 && b > 40 && a == 255, "{r} {b} {a}");
    // the same blur without the lock spreads past the edge
    s.undo();
    assert!(s.set_layer_alpha_lock(id, false));
    blur(&s);
    assert!(at(&s, 18)[3] > 0);
}

#[test]
fn a_copy_from_a_bigger_canvas_pastes_whole() {
    let Some(s) = session(100, 100) else { return };
    // a 400 × 300 canvas's copy: a red block near its top left corner, and a blue one near the
    // bottom right, both outside a 100 × 100 canvas's middle
    let (w, h) = (400usize, 300usize);
    let mut rgba = vec![0u8; w * h * 4];
    let mut block = |x0: usize, y0: usize, c: [u8; 4]| {
        for y in y0..y0 + 20 {
            for x in x0..x0 + 20 {
                rgba[(y * w + x) * 4..][..4].copy_from_slice(&c);
            }
        }
    };
    block(10, 10, [255, 0, 0, 255]);
    block(370, 270, [0, 0, 255, 255]);
    let copied = crate::layers::ThumbnailImage { width: w as u32, height: h as u32, rgba };
    let id = s.paste(copied).unwrap();
    // what is painted (380 × 280) scaled down to the canvas's width, centred: both blocks are there
    let layer = s.copy_layer_contents(id).unwrap();
    let at = |x: usize, y: usize| <[u8; 4]>::try_from(&layer.rgba[(y * 100 + x) * 4..][..4]).unwrap();
    assert_eq!(at(2, 16), [255, 0, 0, 255]);
    assert_eq!(at(97, 82), [0, 0, 255, 255]);
    assert_eq!(at(50, 50)[3], 0);
    // nothing of it is outside the strip it fills
    assert_eq!(at(50, 10)[3], 0);
    assert_eq!(at(50, 90)[3], 0);
    // a small part of a big canvas comes in at its own size, in the middle
    let mut rgba = vec![0u8; w * h * 4];
    for y in 0..10 {
        for x in 380..390 {
            rgba[(y * w + x) * 4..][..4].copy_from_slice(&[0, 255, 0, 255]);
        }
    }
    let id = s.paste(crate::layers::ThumbnailImage { width: w as u32, height: h as u32, rgba }).unwrap();
    let layer = s.copy_layer_contents(id).unwrap();
    let painted = crate::layer_ops::painted_rect(&layer.rgba, 100).unwrap();
    assert_eq!((painted.x0, painted.y0, painted.x1, painted.y1), (45, 45, 55, 55));
}

#[test]
fn a_copy_reads_only_what_is_selected_and_painted_as_the_whole_layer_would_give() {
    use crate::selection::SelectionJoin;
    let Some(s) = session(300, 300) else { return };
    s.set_brush_size(0.3);
    s.set_color(0.2, 0.6, 1.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(60.0, 80.0, 0.0)]);
    s.stroke_add(vec![sample(220.0, 200.0, 40.0)]);
    s.stroke_end(vec![]);
    let current = s.layers().iter().find(|l| l.current).map(|l| l.id).unwrap();
    // the whole layer, as much of each pixel as the selection takes (as copying did)
    let whole = |s: &CanvasSession| {
        let mut pixels = s.copy_layer_contents(current).unwrap().rgba;
        if let Some(mask) = s.shared.lock().selection.clone() {
            for (px, &m) in pixels.as_chunks_mut::<4>().0.iter_mut().zip(&mask.data) {
                for c in px.iter_mut() {
                    *c = ((u16::from(*c) * u16::from(m) + 127) / 255) as u8;
                }
            }
        }
        pixels
    };
    assert!(s.copy_layer().unwrap().rgba == whole(&s));
    // an ellipse over part of the stroke (its soft edge), then one away from any paint
    s.select_shape(true, 100.0, 90.0, 190.0, 170.0, SelectionJoin::Add);
    let copied = s.copy_layer().unwrap();
    assert!(copied.rgba == whole(&s) && copied.rgba.iter().any(|&v| v > 0));
    s.select_none();
    s.select_shape(false, 0.0, 250.0, 40.0, 290.0, SelectionJoin::Add);
    assert!(s.copy_layer().unwrap().rgba.iter().all(|&v| v == 0));
}

#[test]
fn a_private_picture_shows_on_the_canvas_but_not_in_the_thumbnail() {
    let Some(s) = session(100, 100) else { return };
    let photo = crate::layers::ThumbnailImage { width: 100, height: 100, rgba: [255, 0, 0, 255].repeat(100 * 100) };
    let id = s.insert_image(photo, true).unwrap();
    assert!(s.layers().iter().any(|l| l.id == id && l.private));
    assert_eq!(pixel(&s, 50, 50), [255, 0, 0, 255]);
    let dir = std::env::temp_dir().join(format!("procraft-private-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    s.save(dir.to_string_lossy().into_owned()).unwrap();
    let png = std::fs::read(dir.join("thumbnail.png")).unwrap();
    let (w, h, rgba) = crate::brush_files::thumbnail_pixels(&png).unwrap();
    let middle = ((h / 2 * w + w / 2) * 4) as usize;
    assert_eq!(&rgba[middle..middle + 3], &[255, 255, 255], "the thumbnail shows the white background");
    // the canvas itself still shows it, and a paste can be private too
    assert_eq!(pixel(&s, 50, 50), [255, 0, 0, 255]);
    let copied = s.copy_layer().unwrap();
    let pasted = s.paste_private(copied).unwrap();
    assert!(s.layers().iter().any(|l| l.id == pasted && l.private));
    s.undo();
    assert!(s.layers().iter().all(|l| l.id != pasted));
    let _ = std::fs::remove_dir_all(&dir);
}

/// A time-lapse frame is read back at the size frames are kept, whatever the video's, and kept by
/// the core itself: after each stroke it moves a few MB, not dozens (a frame the video's size
/// went to the app and back, and had the page faults of a tablet's drawing at 60 000 a second).
#[test]
fn a_time_lapse_frame_is_read_at_the_size_it_is_kept() {
    let Some(s) = session(2048, 512) else { return };
    let dir = std::env::temp_dir().join(format!("procraft-lapse-size-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let lapse = crate::TimeLapse::new(dir.to_string_lossy().into_owned());
    // the largest video: frames would have been read at its 3840
    lapse.set_settings(crate::TimeLapseSettings { resolution: 2, quality: 1, hevc: false });
    s.stroke_begin(PointerKind::Finger, vec![sample(100.0, 100.0, 0.0)]);
    s.stroke_add(vec![sample(400.0, 300.0, 40.0)]);
    s.stroke_end(vec![]);
    assert!(s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    let frame = lapse.frame(0).unwrap();
    assert_eq!((frame.width, frame.height), (crate::timelapse::FRAME_SIDE, crate::timelapse::FRAME_SIDE));
    // nothing new: no frame
    assert!(!s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    assert_eq!(lapse.count(), 1);
    // not recording: none
    lapse.set_recording(false);
    s.stroke_begin(PointerKind::Finger, vec![sample(100.0, 400.0, 0.0)]);
    s.stroke_end(vec![]);
    assert!(!s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    assert_eq!(lapse.count(), 1);
    let _ = std::fs::remove_dir_all(&dir);
}

/// The panels opened while recording (Layers reading its thumbnails and picking a layer, Brushes
/// drawing its previews and picking a brush, Colours setting a colour, Actions reading the canvas's
/// picture), with the app asking for a frame after each as it does after a change, change nothing on
/// the canvas, so they add no frame: the time-lapse records changes to the canvas only. On a
/// portrait and a landscape canvas, neither side a multiple of 16. Bounds: no frame from the four
/// panels, one from the stroke after them, and no frame kept anything of the green a frame left
/// unfilled shows.
#[test]
fn panels_opened_while_recording_add_no_frame() {
    for (w, h) in [(906, 1283), (1283, 906)] {
        let Ok(gpu) = Gpu::headless() else { return };
        let s = CanvasSession::new(w, h);
        {
            let mut st = s.shared.lock();
            st.window_size = (1024, 1024);
            st.view = Some(View::fit((w, h), (1024, 1024)));
            st.gpu = Some(gpu);
            st.ensure_canvas();
        }
        let dir = std::env::temp_dir().join(format!("procraft-lapse-panels-{}-{w}x{h}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let lapse = crate::TimeLapse::new(dir.to_string_lossy().into_owned());
        let stroke = |y: f32| {
            s.stroke_begin(PointerKind::Finger, vec![sample(100.0, y, 0.0)]);
            s.stroke_add(vec![sample(700.0, y + 200.0, 40.0)]);
            s.stroke_end(vec![]);
        };
        s.set_color(0.1, 0.2, 0.8);
        stroke(100.0);
        assert!(s.record_time_lapse(std::sync::Arc::clone(&lapse)));
        let ask = || s.record_time_lapse(std::sync::Arc::clone(&lapse));
        // Layers
        let layers = s.layers();
        for l in &layers {
            let _ = s.layer_thumbnail(l.id, 96);
        }
        if let Some(l) = layers.first() {
            s.select_layer(l.id);
        }
        let layers_added = ask();
        // Brushes
        let _ = s.brush_preview(0, 0, 300, 60);
        let _ = s.brush_preview(0, 1, 300, 60);
        let _ = s.select_brush(0, 1);
        let brushes_added = ask();
        // Colours
        s.set_color(0.9, 0.4, 0.1);
        let colours_added = ask();
        // Actions
        let _ = s.canvas_thumbnail(256);
        let actions_added = ask();
        let after_panels = lapse.count();
        stroke(500.0);
        assert!(ask());
        println!(
            "{w}x{h}: frames after a stroke and four panels {after_panels}, after the next stroke {}",
            lapse.count()
        );
        assert_eq!([layers_added, brushes_added, colours_added, actions_added], [false; 4], "a panel added a frame");
        assert_eq!((after_panels, lapse.count()), (1, 2));
        for i in 0..lapse.count() {
            let f = lapse.frame(i).unwrap();
            let green = f
                .rgba
                .as_chunks::<4>()
                .0
                .iter()
                .filter(|&&[r, g, b, _]| r < 24 && b < 24 && (105..=165).contains(&g))
                .count();
            assert_eq!(green, 0, "frame {i} has {green} pixels of an unfilled frame's green");
        }
        let _ = std::fs::remove_dir_all(&dir);
    }
}

/// The graphics device lost as a frame is read back (or before): no frame, and nothing panics,
/// whether the read was started before the loss or after it.
/// A window `side` pixels square to draw frames into, as the apps draw them.
fn window_view(s: &CanvasSession, side: u32) -> procraft_gpu::wgpu::TextureView {
    use procraft_gpu::wgpu;
    let gpu = s.shared.lock().gpu.clone().unwrap();
    gpu.device
        .create_texture(&wgpu::TextureDescriptor {
            label: Some("window"),
            size: wgpu::Extent3d { width: side, height: side, depth_or_array_layers: 1 },
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format: wgpu::TextureFormat::Rgba8Unorm,
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
            view_formats: &[],
        })
        .create_view(&Default::default())
}

/// A time-lapse frame asked for right after a stroke whose end the frames lay a share at a time
/// is taken by the frame that has laid it, from the composite as that frame leaves it: the ask
/// returns at once, neither waiting for the frames nor laying the end at
/// once in a hold of the canvas; nothing is kept while the end is still being laid; the frame kept
/// is the stroke with its end. With no frames drawn, it is taken at once and kept before the ask
/// returns.
#[test]
fn a_time_lapse_frame_is_taken_by_the_frame_that_lays_a_strokes_end() {
    use std::time::{Duration, Instant};
    let Some(s) = session(512, 512) else { return };
    let Some((set, index)) = library_brush(&s, |b| b.name == "Easterly") else { return };
    assert!(s.select_brush(set, index));
    s.set_brush_size(1.0);
    // the end laid whole again (as one its end taper reaches back over is), a piece at each frame
    s.shared.lock().canvas.as_mut().unwrap().set_relay_at_once(Duration::ZERO);
    s.shared.lock().canvas.as_mut().unwrap().lay_ends_whole(true);
    let gpu = s.shared.lock().gpu.clone().unwrap();
    let view = window_view(&s, 512);
    let frame = || {
        let format = procraft_gpu::wgpu::TextureFormat::Rgba8Unorm;
        s.draw(&view, format, (512, 512), procraft_engine::profile::Profile::Srgb, Instant::now());
        gpu.flush();
    };
    let lays = || s.shared.lock().canvas.as_deref().is_some_and(procraft_gpu::Canvas::lays_over_frames);
    let stroke = |y: f32| {
        s.stroke_begin(PointerKind::Stylus, vec![sample(40.0, y, 0.0)]);
        for i in 1..60 {
            let x = 40.0 + i as f32 * 7.0;
            s.stroke_add(vec![PenSample { pressure: 0.5, ..sample(x, y + (x / 40.0).sin() * 60.0, i as f64 * 8.0) }]);
            if i % 2 == 0 {
                frame();
            }
        }
        s.stroke_end(vec![]);
        frame();
    };
    let dir = std::env::temp_dir().join(format!("procraft-lapse-end-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let lapse = crate::TimeLapse::new(dir.to_string_lossy().into_owned());
    let keeper = s.shared.lock().lapse_keeper.clone();
    stroke(200.0);
    assert!(lays(), "the stroke's end is laid over frames");
    let t = Instant::now();
    assert!(s.record_time_lapse(std::sync::Arc::clone(&lapse)), "asked for");
    let asked = t.elapsed();
    assert!(lays(), "the ask left the stroke's end to the frames");
    let mut frames = 0;
    while lays() && frames < 1000 {
        assert!(keeper.settle(crate::timelapse::KEEP_MOST));
        assert_eq!(lapse.count(), 0, "a frame kept while the end is still being laid");
        frame();
        frames += 1;
    }
    assert!(keeper.settle(crate::timelapse::KEEP_MOST));
    println!("the ask took {asked:?}; the end laid over {frames} frames, the last taking the picture");
    assert!(asked < Duration::from_millis(50), "{asked:?}");
    assert!(frames > 1, "laid over {frames} frames");
    assert_eq!(lapse.count(), 1, "the frame that laid the end took it");
    // the frame kept is the picture with the end: taken again with no frames drawn (they stop),
    // the same, so not kept again
    s.shared.lock().frame_drawn_at = None;
    assert!(!s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    assert_eq!(lapse.count(), 1);
    // no frames drawn: taken at once, the end laid by it, kept before the ask returns
    stroke(350.0);
    assert!(lays());
    s.shared.lock().frame_drawn_at = None;
    assert!(s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    assert_eq!(lapse.count(), 2);
    assert!(!lays());
    assert_eq!(gpu.errors(), 0);
    let _ = std::fs::remove_dir_all(&dir);
}

/// A time-lapse frame asked for while the frames lay a long stroke's end slowly waits for them
/// however long they take, laying none of it at once (that held the frames and touches for most
/// of a second at a time while painting quickly on a large canvas), and the frame that lays the
/// last of it takes it, with no second ask (before, a wait of three seconds ran out and the frame
/// was left out until the next stroke's).
#[test]
fn a_time_lapse_frame_waits_on_slow_frames_and_lays_nothing_at_once() {
    use std::time::{Duration, Instant};
    let Some(s) = session(512, 512) else { return };
    let Some((set, index)) = library_brush(&s, |b| b.name == "Easterly") else { return };
    assert!(s.select_brush(set, index));
    s.set_brush_size(0.5);
    // the end laid whole again (as one its end taper reaches back over is), a stamp at each frame,
    // the frames drawn slowly
    {
        let mut st = s.shared.lock();
        let canvas = st.canvas.as_mut().unwrap();
        canvas.set_relay_at_once(Duration::ZERO);
        canvas.lay_ends_whole(true);
        canvas.set_work_at_once(1);
    }
    let gpu = s.shared.lock().gpu.clone().unwrap();
    let view = window_view(&s, 512);
    let frame = || {
        let format = procraft_gpu::wgpu::TextureFormat::Rgba8Unorm;
        s.draw(&view, format, (512, 512), procraft_engine::profile::Profile::Srgb, Instant::now());
        gpu.flush();
    };
    let lays = || s.shared.lock().canvas.as_deref().is_some_and(procraft_gpu::Canvas::lays_over_frames);
    s.stroke_begin(PointerKind::Stylus, vec![sample(40.0, 200.0, 0.0)]);
    // back and forth across the canvas, long enough for hundreds of stamps
    for i in 1..200 {
        let x = 40.0 + (i % 100) as f32 * 4.3;
        let y = 100.0 + (i / 100) as f32 * 90.0 + (x / 40.0).sin() * 30.0;
        s.stroke_add(vec![PenSample { pressure: 0.5, ..sample(x, y, i as f64 * 8.0) }]);
        if i % 2 == 0 {
            frame();
        }
    }
    s.stroke_end(vec![]);
    frame();
    assert!(lays(), "the stroke's end is laid over frames");
    let dir = std::env::temp_dir().join(format!("procraft-lapse-left-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let lapse = crate::TimeLapse::new(dir.to_string_lossy().into_owned());
    let keeper = s.shared.lock().lapse_keeper.clone();
    assert!(s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    // slow frames a while: still laying it, none laid at once, nothing kept
    for _ in 0..40 {
        frame();
        std::thread::sleep(Duration::from_millis(20));
    }
    assert!(lays(), "the ask laid the end at once");
    assert!(keeper.settle(crate::timelapse::KEEP_MOST));
    assert_eq!(lapse.count(), 0, "kept before the end was laid");
    // the rest laid as frames lay it by default: the frame that lays the last of it takes it
    {
        let mut st = s.shared.lock();
        let canvas = st.canvas.as_mut().unwrap();
        canvas.set_relay_at_once(Duration::from_millis(6));
        canvas.set_work_at_once(64 << 20);
    }
    let mut frames = 0;
    while lays() && frames < 20_000 {
        frame();
        frames += 1;
    }
    println!("its end laid over {frames} more frames");
    assert!(keeper.settle(crate::timelapse::KEEP_MOST));
    assert_eq!(lapse.count(), 1, "kept once the end is laid, with no second ask");
    let _ = std::fs::remove_dir_all(&dir);
    assert_eq!(gpu.errors(), 0);
}

/// The Reference window's picture of the canvas, read right after a stroke whose end the frames lay
/// a share at a time, waits for them (the state let go meanwhile) rather than laying the rest at once
/// in its hold of it, and waits for the GPU's copy with the state let go: the frames and the app's
/// touches went on waiting behind that read, most of a second after a heavy brush's stroke on a
/// large canvas. Its picture is the stroke with its end.
#[test]
fn the_reference_windows_read_of_the_canvas_leaves_a_strokes_end_to_the_frames() {
    use std::time::{Duration, Instant};
    let Some(s) = session(512, 512) else { return };
    let Some((set, index)) = library_brush(&s, |b| b.name == "Easterly") else { return };
    assert!(s.select_brush(set, index));
    s.set_brush_size(1.0);
    // the end laid whole again (as one its end taper reaches back over is), a piece at each frame
    s.shared.lock().canvas.as_mut().unwrap().set_relay_at_once(Duration::ZERO);
    s.shared.lock().canvas.as_mut().unwrap().lay_ends_whole(true);
    let gpu = s.shared.lock().gpu.clone().unwrap();
    let view = window_view(&s, 512);
    let frame = || {
        let format = procraft_gpu::wgpu::TextureFormat::Rgba8Unorm;
        s.draw(&view, format, (512, 512), procraft_engine::profile::Profile::Srgb, Instant::now());
        gpu.flush();
    };
    let lays = || s.shared.lock().canvas.as_deref().is_some_and(procraft_gpu::Canvas::lays_over_frames);
    s.stroke_begin(PointerKind::Stylus, vec![sample(40.0, 200.0, 0.0)]);
    for i in 1..60 {
        let x = 40.0 + i as f32 * 7.0;
        s.stroke_add(vec![PenSample { pressure: 0.5, ..sample(x, 200.0 + (x / 40.0).sin() * 60.0, i as f64 * 8.0) }]);
        if i % 2 == 0 {
            frame();
        }
    }
    s.stroke_end(vec![]);
    frame();
    assert!(lays(), "the stroke's end is laid over frames");
    let reader = {
        let s = std::sync::Arc::clone(&s);
        std::thread::spawn(move || s.reference_canvas(256))
    };
    std::thread::sleep(Duration::from_millis(100));
    assert!(lays(), "the read left the stroke's end to the frames");
    let mut frames = 0;
    while lays() && frames < 1000 {
        frame();
        frames += 1;
    }
    let read = reader.join().unwrap().expect("a picture");
    println!("the stroke's end laid over {frames} frames, then read");
    assert!(frames > 1, "laid over {frames} frames");
    // the picture is the stroke with its end: as the canvas reads now
    assert_eq!(s.canvas_thumbnail(256).map(|t| t.rgba), Some(read.rgba));
    assert_eq!(gpu.errors(), 0);
}

/// A time-lapse frame asked for while the frames lay one stroke's end, the pen already on the
/// next, is taken once that end is laid: the open stroke's work, which comes as the pen moves,
/// isn't waited for (a read waited for that stroke to end, up to three seconds, and then took part
/// of it). Bound: kept within a second, while the next stroke is still being drawn (for 2.5 s).
#[test]
fn a_time_lapse_frame_waits_for_an_ended_strokes_end_not_the_stroke_begun_after_it() {
    use std::time::{Duration, Instant};
    let Some(s) = session(512, 512) else { return };
    let Some((set, index)) = library_brush(&s, |b| b.name == "Easterly") else { return };
    assert!(s.select_brush(set, index));
    s.set_brush_size(1.0);
    // the end laid whole again (as one its end taper reaches back over is), a piece at each frame
    s.shared.lock().canvas.as_mut().unwrap().set_relay_at_once(Duration::ZERO);
    s.shared.lock().canvas.as_mut().unwrap().lay_ends_whole(true);
    let gpu = s.shared.lock().gpu.clone().unwrap();
    let view = window_view(&s, 512);
    let frame = || {
        let format = procraft_gpu::wgpu::TextureFormat::Rgba8Unorm;
        s.draw(&view, format, (512, 512), procraft_engine::profile::Profile::Srgb, Instant::now());
        gpu.flush();
    };
    let lays = || s.shared.lock().canvas.as_deref().is_some_and(procraft_gpu::Canvas::lays_over_frames);
    let at = |i: usize, y: f32| {
        let x = 40.0 + (i % 60) as f32 * 7.0;
        PenSample { pressure: 0.5, ..sample(x, y + (x / 40.0).sin() * 60.0, i as f64 * 8.0) }
    };
    s.stroke_begin(PointerKind::Stylus, vec![sample(40.0, 150.0, 0.0)]);
    for i in 1..60 {
        s.stroke_add(vec![at(i, 150.0)]);
        if i % 2 == 0 {
            frame();
        }
    }
    s.stroke_end(vec![]);
    frame();
    assert!(lays(), "the stroke's end is laid over frames");
    // the next stroke begun at once, a time-lapse frame asked for meanwhile
    s.stroke_begin(PointerKind::Stylus, vec![sample(40.0, 350.0, 0.0)]);
    let dir = std::env::temp_dir().join(format!("procraft-lapse-open-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let lapse = crate::TimeLapse::new(dir.to_string_lossy().into_owned());
    assert!(s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    let started = Instant::now();
    let (mut events, mut kept_at) = (0, None);
    while started.elapsed() < Duration::from_millis(2500) {
        frame();
        // the pen goes on as each frame is drawn: the open stroke always has work queued
        events += 1;
        s.stroke_add(vec![at(events, 350.0)]);
        if kept_at.is_none() && lapse.count() > 0 {
            kept_at = Some(started.elapsed());
        }
        std::thread::sleep(Duration::from_millis(4));
    }
    s.stroke_end(vec![]);
    while lays() {
        frame();
    }
    let _ = std::fs::remove_dir_all(&dir);
    println!("the time-lapse frame kept after {kept_at:?} of the next stroke's 2.5 s ({events} pen events)");
    let kept_at = kept_at.expect("the frame kept while the next stroke was being drawn");
    assert!(kept_at < Duration::from_secs(1), "{kept_at:?}");
    assert_eq!(gpu.errors(), 0);
}

/// A time-lapse frame asked for while frames were being drawn, and not taken when they stopped
/// (the app leaving the artwork), is taken by the save made then, and every frame taken is kept
/// before the save ends: the app may make a video of them next.
#[test]
fn a_time_lapse_frame_asked_for_and_not_taken_is_kept_by_the_save() {
    use std::time::Instant;
    let Some(s) = session(256, 256) else { return };
    let gpu = s.shared.lock().gpu.clone().unwrap();
    let view = window_view(&s, 256);
    let frame = || {
        let format = procraft_gpu::wgpu::TextureFormat::Rgba8Unorm;
        s.draw(&view, format, (256, 256), procraft_engine::profile::Profile::Srgb, Instant::now());
        gpu.flush();
    };
    let dir = std::env::temp_dir().join(format!("procraft-lapse-save-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let path = dir.to_string_lossy().into_owned();
    let lapse = crate::TimeLapse::new(path.clone());
    s.set_brush_size(0.3);
    s.set_color(0.0, 0.0, 0.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(20.0, 128.0, 0.0)]);
    s.stroke_add(vec![sample(230.0, 128.0, 40.0)]);
    s.stroke_end(vec![]);
    frame();
    // frames being drawn: asked for, left to the next frame, which never comes
    assert!(s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    assert_eq!(lapse.count(), 0);
    s.save(path.clone()).unwrap();
    assert_eq!(lapse.count(), 1, "the save took the frame asked for and kept it");
    let kept = lapse.frame(0).unwrap();
    let middle = (((kept.height / 2) * kept.width + kept.width / 2) * 4) as usize;
    assert!(kept.rgba[middle..middle + 3].iter().all(|&c| c < 100), "the stroke: {:?}", &kept.rgba[middle..middle + 3]);
    let _ = std::fs::remove_dir_all(&dir);
    assert_eq!(gpu.errors(), 0);
}

/// Time-lapse frames asked for after strokes one after another (each stroke's end laid over
/// frames as the next begins) come one after each stroke, in order (a stroke shown in a frame is
/// in every frame after), and the last shows every stroke: none is left out. Bounds: a frame for every stroke; the asks hold the
/// canvas no longer than a 60 Hz frame (16.7 ms).
#[test]
fn time_lapse_frames_of_strokes_one_after_another_come_in_order_and_leave_none_out() {
    let Some(run) = lapse_back_to_back(1024, 1, 8, "Easterly", 0.3, 20) else { return };
    run.print();
    assert!(run.in_order, "frames out of order");
    assert!(run.last_all, "a stroke missing from the last frame");
    assert!(run.kept as usize >= run.strokes, "{} frames for {} strokes", run.kept, run.strokes);
    assert!(run.lapse_held < std::time::Duration::from_micros(16_700), "{:?}", run.lapse_held);
}

/// What reading a time-lapse frame right after each stroke (as the apps do, the time-lapse kept
/// by default) costs the frames and the app's thread, for a few heavy brushes (wet, dual, big; at
/// their full size) on a large canvas (`LAPSE_COST_SIDE`, 2944x1840, ten layers), the frames drawn
/// on a thread of their own every 8 ms as the apps draw them: the longest frame over the two
/// seconds after the lift, and the app thread's longest wait for the state (asked every 2 ms),
/// each with the frame read and without. Bound: at the middle brush, the read adds no more than a
/// 60 Hz frame (16.7 ms) to the longest frame (a read that laid the stroke's end at once, in its
/// hold of the state, held the frames up to seconds behind that work). Run with `--ignored
/// --nocapture`.
#[test]
#[ignore]
fn time_lapse_frame_cost() {
    use std::sync::Arc;
    use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
    use std::time::{Duration, Instant};
    let side = std::env::var("LAPSE_COST_SIDE").unwrap_or_else(|_| "2944x1840".to_owned());
    let (w, h) =
        side.split_once('x').and_then(|(w, h)| Some((w.parse().ok()?, h.parse().ok()?))).unwrap_or((2944u32, 1840u32));
    let Ok(gpu) = Gpu::headless() else { return eprintln!("skipped: no GPU") };
    let s = CanvasSession::new(w, h);
    {
        let mut st = s.shared.lock();
        st.window_size = (1600, 1600);
        st.view = Some(View::fit((w, h), (1600, 1600)));
        st.gpu = Some(gpu.clone());
        st.ensure_canvas();
    }
    for _ in 1..10 {
        s.add_layer();
    }
    // the longest frame since last reset, in microseconds
    let longest_frame = Arc::new(AtomicU64::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let frames = {
        let (s, stop, gpu, longest) = (Arc::clone(&s), Arc::clone(&stop), gpu.clone(), Arc::clone(&longest_frame));
        std::thread::spawn(move || {
            let view = window_view(&s, 1600);
            while !stop.load(Ordering::Relaxed) {
                let started = Instant::now();
                let format = procraft_gpu::wgpu::TextureFormat::Rgba8Unorm;
                s.draw(&view, format, (1600, 1600), procraft_engine::profile::Profile::Srgb, started);
                gpu.flush();
                longest.fetch_max(started.elapsed().as_micros() as u64, Ordering::Relaxed);
                std::thread::sleep(Duration::from_millis(8).saturating_sub(started.elapsed()));
            }
        })
    };
    let dir = std::env::temp_dir().join(format!("procraft-lapse-cost-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let lapse = crate::TimeLapse::new(dir.to_string_lossy().into_owned());
    let ms = |d: Duration| d.as_secs_f64() * 1000.0;
    let mut added = Vec::new();
    println!(
        "brush\tlongest frame without the read, ms\twith it\tthe app thread's longest wait without, ms\twith\tthe read, ms"
    );
    for name in ["Quagga", "Easterly", "Kingsley", "Dunlin", "Pin Oak", "Copperwing"] {
        let Some((set, index)) = library_brush(&s, |b| b.name == name) else { continue };
        assert!(s.select_brush(set, index));
        s.set_brush_size(1.0);
        // a first stroke warms the brush up; then one without the read and one with it
        let mut seen = Vec::new();
        for round in 0..3 {
            let y0 = 300.0 + 300.0 * round as f32;
            s.stroke_begin(PointerKind::Stylus, vec![sample(100.0, y0, 0.0)]);
            for i in 1..=150 {
                let x = 100.0 + i as f32 * 9.0;
                let y = y0 + (x / 90.0).sin() * 150.0;
                s.stroke_add(vec![PenSample { pressure: 0.6, ..sample(x, y, i as f64 * 8.3) }]);
                std::thread::sleep(Duration::from_micros(8300));
            }
            longest_frame.store(0, Ordering::Relaxed);
            s.stroke_end(vec![]);
            // the app's thread asks for the state every 2 ms (touches, gestures) meanwhile
            let probing = Arc::new(AtomicBool::new(true));
            let prober = {
                let (s, probing) = (Arc::clone(&s), Arc::clone(&probing));
                std::thread::spawn(move || {
                    let mut longest = Duration::ZERO;
                    while probing.load(Ordering::Relaxed) {
                        let t = Instant::now();
                        drop(s.shared.lock());
                        longest = longest.max(t.elapsed());
                        std::thread::sleep(Duration::from_millis(2));
                    }
                    longest
                })
            };
            let t = Instant::now();
            if round == 2 {
                s.record_time_lapse(Arc::clone(&lapse));
            }
            let read = t.elapsed();
            std::thread::sleep(Duration::from_secs(2).saturating_sub(t.elapsed()));
            probing.store(false, Ordering::Relaxed);
            let waited = prober.join().unwrap();
            let frame = Duration::from_micros(longest_frame.load(Ordering::Relaxed));
            seen.push((frame, waited, read));
            s.undo();
        }
        let ((without, waited_without, _), (with, waited_with, read)) = (seen[1], seen[2]);
        println!(
            "{name}\t{:.1}\t{:.1}\t{:.1}\t{:.1}\t{:.1}",
            ms(without),
            ms(with),
            ms(waited_without),
            ms(waited_with),
            ms(read)
        );
        added.push(with.saturating_sub(without));
    }
    stop.store(true, Ordering::Relaxed);
    frames.join().unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    added.sort();
    let middle = added.get(added.len() / 2).copied().unwrap_or_default();
    println!("the read adds to the longest frame: middle {middle:?}, most {:?}", added.last());
    assert!(middle < Duration::from_micros(16_700), "{middle:?}");
}

#[test]
fn a_time_lapse_frame_on_a_lost_device_is_none_without_a_panic() {
    let Some(s) = session(256, 256) else { return };
    let dir = std::env::temp_dir().join(format!("procraft-lapse-lost-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let lapse = crate::TimeLapse::new(dir.to_string_lossy().into_owned());
    s.stroke_begin(PointerKind::Finger, vec![sample(100.0, 100.0, 0.0)]);
    s.stroke_end(vec![]);
    assert!(s.record_time_lapse(std::sync::Arc::clone(&lapse)));
    // a read started, the device lost before it is waited for
    let pending = {
        let mut guard = s.shared.lock();
        let st = &mut *guard;
        let (canvas, gpu) = (st.canvas.as_mut().unwrap(), st.gpu.as_ref().unwrap());
        let pending = canvas.start_composite_thumbnail_without(gpu, &mut st.doc, 64, &[]);
        gpu.device.destroy();
        pending
    };
    let read = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| pending.pixels()));
    assert!(read.is_ok_and(|r| r.is_err()), "a read on a lost device fails, not panics");
    // and the next frames read after it
    s.stroke_begin(PointerKind::Finger, vec![sample(150.0, 150.0, 0.0)]);
    s.stroke_end(vec![]);
    let recorded = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        (s.time_lapse_frame(64).is_none(), s.record_time_lapse(std::sync::Arc::clone(&lapse)))
    }));
    assert_eq!(recorded.ok(), Some((true, false)));
    assert!(s.shared.lock().gpu.as_ref().is_some_and(Gpu::is_lost));
    assert_eq!(lapse.count(), 1);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn a_private_picture_stays_out_of_the_time_lapse() {
    let Some(s) = session(100, 100) else { return };
    let dir = std::env::temp_dir().join(format!("procraft-private-lapse-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let artwork = dir.to_string_lossy().into_owned();
    let lapse = crate::TimeLapse::new(artwork.clone());
    // a frame as the apps record one after each change, as large as the video
    let record = |s: &CanvasSession| {
        let shot = s.time_lapse_frame(crate::time_lapse_side(lapse.settings())).unwrap();
        lapse.record(shot.rgba, shot.width, shot.height)
    };
    // what the replay (and the video made of the frames) shows at (x, y) of frame `i`
    let shown = |i: u32, x: u32, y: u32| {
        let f = lapse.frame(i).unwrap();
        let at = ((y * f.width + x) * 4) as usize;
        [f.rgba[at], f.rgba[at + 1], f.rgba[at + 2]]
    };
    let white = |c: [u8; 3]| c.iter().all(|&v| v > 235);
    let photo = crate::layers::ThumbnailImage { width: 100, height: 100, rgba: [255, 0, 0, 255].repeat(100 * 100) };
    let id = s.insert_image(photo, true).unwrap();
    assert!(record(&s));
    assert!(white(shown(0, 50, 50)), "the picture is recorded: {:?}", shown(0, 50, 50));
    // a stroke on a layer over it is recorded as ever, the picture under it still left out
    s.add_layer();
    s.set_color(0.0, 0.0, 1.0);
    s.set_brush_size(0.3);
    s.stroke_begin(PointerKind::Finger, vec![sample(10.0, 20.0, 0.0)]);
    s.stroke_add(vec![sample(90.0, 20.0, 40.0)]);
    s.stroke_end(vec![]);
    assert_eq!((pixel(&s, 50, 20), pixel(&s, 50, 50)), ([0, 0, 255, 255], [255, 0, 0, 255]), "the canvas shows both");
    assert!(record(&s));
    let [r, g, b] = shown(1, 50, 20);
    assert!(b > 200 && r < 60 && g < 60, "the stroke: {:?}", [r, g, b]);
    assert!(white(shown(1, 50, 50)), "the picture is recorded: {:?}", shown(1, 50, 50));
    // kept private in the artwork's file: opened again, its frames still leave it out
    s.save(artwork.clone()).unwrap();
    let opened = CanvasSession::open(artwork).unwrap();
    let Some(gpu) = s.shared.lock().gpu.clone() else { return };
    opened.use_gpu(gpu);
    assert!(opened.layers().iter().any(|l| l.id == id && l.private));
    let frame = opened.time_lapse_frame(crate::time_lapse_side(lapse.settings())).unwrap();
    let middle = ((50 * frame.width + 50) * 4) as usize;
    assert_eq!(&frame.rgba[middle..middle + 4], &[255, 255, 255, 255]);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn no_stroke_or_undo_joins_a_plugins_change_while_it_goes_on() {
    let Some(s) = session(100, 100) else { return };
    s.set_brush_size(0.3);
    let dot = |x: f32| {
        s.stroke_begin(PointerKind::Finger, vec![sample(x, 50.0, 0.0)]);
        s.stroke_end(vec![]);
    };
    dot(20.0);
    {
        let _step = s.plugin_step();
        // a stroke and an undo while a plugin's action runs: neither happens
        dot(80.0);
        assert!(s.undo().is_none());
    }
    assert_eq!(pixel(&s, 80, 50), [255, 255, 255, 255], "no stroke while the plugin's change went on");
    assert_eq!(pixel(&s, 20, 50)[0], 0, "and the one before wasn't undone");
    // once it has ended, both go as ever
    dot(80.0);
    assert_eq!(pixel(&s, 80, 50)[0], 0);
    s.undo();
    assert_eq!(pixel(&s, 80, 50), [255, 255, 255, 255]);
}

#[test]
fn a_shape_snapped_with_symmetry_on_shows_its_copy_while_held() {
    use crate::guide::{GuideType, SymmetryType};
    use crate::quickshape::QuickShapeKind;
    let Some(s) = session(100, 100) else { return };
    s.set_brush_size(0.2);
    s.set_guide_on(true);
    s.set_guide_kind(GuideType::Symmetry);
    s.set_guide_symmetry(SymmetryType::Vertical, false);
    s.set_guide_assisted(true);
    // a wavering line on the left half, held: a straight line, and its copy on the right
    let at = |i: usize| {
        let t = i as f32 / 40.0;
        sample(10.0 + 30.0 * t, 20.0 + 60.0 * t + 1.5 * (t * 25.0).sin(), i as f64 * 8.0)
    };
    s.stroke_begin(PointerKind::Finger, vec![at(0)]);
    s.stroke_add((1..=40).map(at).collect());
    assert_eq!(s.quickshape_hold().expect("a shape").kind, QuickShapeKind::Line);
    // (25, 50) is on the line, (75, 50) its copy
    assert_eq!(pixel(&s, 25, 50)[0], 0);
    assert_eq!(pixel(&s, 75, 50)[0], 0, "the copy shows while the pen is down");
    s.stroke_end(vec![]);
    s.quickshape_done();
    assert_eq!(pixel(&s, 75, 50)[0], 0, "and is kept");
}

#[test]
fn the_drawing_guide_mirrors_and_assists_strokes() {
    use crate::guide::{GuideType, SymmetryType};
    let Some(s) = session(100, 100) else { return };
    s.set_brush_size(0.3);
    // symmetry: a dot on the left is drawn on the right too
    s.set_guide_on(true);
    s.set_guide_kind(GuideType::Symmetry);
    s.set_guide_symmetry(SymmetryType::Vertical, false);
    s.set_guide_assisted(true);
    s.stroke_begin(PointerKind::Finger, vec![sample(20.0, 30.0, 0.0)]);
    s.stroke_end(vec![]);
    assert_eq!(pixel(&s, 80, 30)[0], 0);
    // the grid keeps a slanting stroke level
    s.set_guide_kind(GuideType::Grid);
    s.stroke_begin(PointerKind::Finger, vec![sample(10.0, 70.0, 0.0)]);
    s.stroke_add((1..=20).map(|i| sample(10.0 + i as f32 * 3.0, 70.0 + i as f32 * 0.6, f64::from(i) * 8.0)).collect());
    s.stroke_end(vec![]);
    assert_eq!(pixel(&s, 60, 70)[0], 0);
    assert_eq!(pixel(&s, 60, 80), [255, 255, 255, 255]);
    let info = s.guide();
    assert!(info.on && info.assisted && !info.lines.is_empty());
    // a wavering stroke near the diagonal keeps the direction it set out in, not zigzagging
    // between the grid's two
    s.stroke_begin(PointerKind::Finger, vec![sample(10.0, 10.0, 0.0)]);
    s.stroke_add(
        (1..=20)
            .map(|i| sample(10.0 + i as f32 * 2.0, 10.0 + i as f32 * 2.0 + [1.5, -1.5][i % 2], i as f64 * 8.0))
            .collect(),
    );
    s.stroke_end(vec![]);
    let row = (10..55).filter(|&x| pixel(&s, x, 10)[0] == 0).count();
    let column = (10..55).filter(|&y| pixel(&s, 10, y)[0] == 0).count();
    // (the symmetry dot is at 20, 30)
    let off =
        [(20, 20), (30, 30), (40, 40), (30, 20), (40, 25)].iter().filter(|&&(x, y)| pixel(&s, x, y)[0] == 0).count();
    assert!(row.max(column) > 40 && row.min(column) < 8 && off == 0, "row {row} column {column} off the line {off}");
    // drawing assist belongs to the layer: a new one draws freely
    let assisted = s.layers().iter().find(|l| l.current).map(|l| l.id).unwrap();
    assert!(s.layers().iter().any(|l| l.id == assisted && l.assisted));
    s.add_layer();
    assert!(!s.guide().assisted);
    s.stroke_begin(PointerKind::Finger, vec![sample(10.0, 90.0, 0.0)]);
    s.stroke_add((1..=20).map(|i| sample(10.0 + i as f32 * 3.0, 90.0 - i as f32 * 0.6, f64::from(i) * 8.0)).collect());
    s.stroke_end(vec![]);
    assert_eq!(pixel(&s, 70, 78)[0], 0);
    assert_eq!(pixel(&s, 70, 90), [255, 255, 255, 255]);
    assert!(s.select_layer(assisted));
    assert!(s.guide().assisted);
    // the editor fits the canvas in the middle of the window, and cancelling puts the guide and
    // the view back, each moving there over its time
    let before = s.view_matrix();
    let settled = || {
        std::thread::sleep(std::time::Duration::from_secs_f32(0.3));
        s.shared.lock().step_view_motion();
    };
    s.guide_edit_begin();
    settled();
    assert_ne!(s.view_matrix(), before);
    s.set_guide_look(0.5, 0.5, 30.0, 0.7);
    assert_eq!(s.guide().size, 30.0);
    s.guide_edit_end(false);
    assert_eq!(s.guide().size, 71.0);
    settled();
    assert_eq!(s.view_matrix(), before);
    // perspective points are added by tapping, three at most
    s.set_guide_kind(GuideType::Perspective);
    assert_eq!(s.touch_vanishing_point(5.0, 50.0), Some(0));
    assert_eq!(s.touch_vanishing_point(6.0, 50.0), Some(0));
    assert_eq!(s.touch_vanishing_point(95.0, 50.0), Some(1));
    s.remove_vanishing_point(1);
    assert_eq!(s.guide().vanishing.len(), 2);
}

#[test]
fn a_group_s_lock_shows_on_its_layers_and_their_unlock_takes_it_off() {
    use crate::layers::{Blocked, LayerOption as O};
    let Some(s) = session(64, 64) else { return };
    let lower = s.layers()[0].id;
    let upper = s.add_layer();
    assert!(s.pick_layer(lower));
    let group = s.group_picked();
    assert_ne!(group, 0);
    let locked = |id| s.layers().iter().find(|l| l.id == id).unwrap().locked;
    // as measured: its layers show locked, offer the locked menu and take no paint
    assert!(s.set_layer_locked(upper, true));
    assert!(s.set_layer_locked(group, true));
    assert!(locked(lower) && locked(upper));
    assert!(!s.layer_options(lower).iter().any(|r| r.option == O::Rename));
    assert!(s.select_layer(lower));
    assert_eq!(s.why_blocked(), Some(Blocked::Locked));
    // unlocking the group leaves a layer's own lock
    assert!(s.set_layer_locked(group, false));
    assert!(!locked(lower) && locked(upper));
    assert_eq!(s.why_blocked(), None);
    // locked by its group alone, a layer's Unlock unlocks the group: one undo step, called so
    assert!(s.set_layer_locked(group, true));
    assert_eq!(s.lock_said(lower, false), "Unlock Layer Group");
    assert_eq!(s.lock_said(upper, false), "Unlock layer");
    assert!(s.set_layer_locked(lower, false));
    assert!(!locked(group) && !locked(lower) && locked(upper));
    assert_eq!(s.undo().as_deref(), Some("unlock Layer Group"));
    assert!(locked(group) && locked(lower));
    // a group's step is named as measured ("Undo unlock Layer Group")
    assert!(s.set_layer_locked(group, false));
    assert_eq!(s.undo().as_deref(), Some("unlock Layer Group"));
}

#[test]
fn drawing_assist_is_a_step_and_a_mask_follows_its_layer() {
    let Some(s) = session(64, 64) else { return };
    let layer = s.layers()[0].id;
    let mask = s.add_mask(layer).unwrap();
    let assisted = |id| s.layers().iter().find(|l| l.id == id).unwrap().assisted;
    // as measured: the mask shows its layer's, and the change is a named step
    assert!(s.select_layer(layer));
    s.set_guide_assisted(true);
    assert!(assisted(layer) && assisted(mask));
    assert_eq!(s.undo().as_deref(), Some("Drawing Assist on"));
    assert!(!assisted(layer) && !assisted(mask));
}

#[test]
fn a_layer_s_options_follow_what_it_is() {
    use crate::layers::{LayerOption as O, LayerOptionRow, LayerType};
    let s = CanvasSession::new(64, 64);
    let bottom = s.layers()[0].id;
    let top = s.add_layer();
    let options = |id| s.layer_options(id).into_iter().map(|r: LayerOptionRow| r.option).collect::<Vec<_>>();
    let row = |id, o| s.layer_options(id).into_iter().find(|r| r.option == o).unwrap();
    // a paint layer with one under it: everything but the text's and a group's, Drawing Assist
    // once the guide has been on (still offered with it off again)
    assert!(!options(top).contains(&O::DrawingAssist));
    s.set_guide_on(true);
    s.set_guide_on(false);
    let mut paint_rows = vec![
        O::Rename,
        O::Select,
        O::Copy,
        O::Fill,
        O::Clear,
        O::AlphaLock,
        O::Mask,
        O::ClippingMask,
        O::DrawingAssist,
    ];
    #[cfg(feature = "generation")]
    paint_rows.push(O::ControlLayer);
    paint_rows.extend([O::Invert, O::Reference, O::MergeDown, O::CombineDown]);
    assert_eq!(options(top), paint_rows);
    // the bottom one has nothing to merge into or clip to
    assert!(!options(bottom).contains(&O::MergeDown) && !options(bottom).contains(&O::ClippingMask));
    // nor is anything merged or combined onto a locked one, as measured
    assert!(s.set_layer_locked(bottom, true));
    assert!(!options(top).contains(&O::MergeDown) && !options(top).contains(&O::CombineDown));
    assert!(s.set_layer_locked(bottom, false));
    // switches say whether they are on
    assert!(s.set_layer_alpha_lock(top, true));
    assert_eq!(row(top, O::AlphaLock).switch_on, Some(true));
    assert_eq!(row(top, O::Fill).switch_on, None);
    // locked, as measured: only what leaves its pixels, name and place as they are
    assert!(s.set_layer_locked(top, true));
    let mut locked_rows = vec![O::Select, O::Copy, O::Mask, O::ClippingMask, O::DrawingAssist];
    #[cfg(feature = "generation")]
    locked_rows.push(O::ControlLayer);
    locked_rows.push(O::Reference);
    assert_eq!(options(top), locked_rows);
    // with a mask, no second one: Merge Mask last instead; the mask's own menu is short
    let mask = s.add_mask(bottom).unwrap();
    let with_mask = options(bottom);
    assert!(!with_mask.contains(&O::Mask) && with_mask.last() == Some(&O::MergeMask));
    assert_eq!(options(mask), [O::Rename, O::Select, O::Fill, O::Clear, O::Invert]);
    // a locked mask's menu is empty, as measured
    assert!(s.set_layer_locked(mask, true));
    assert!(options(mask).is_empty());
    assert!(s.set_layer_locked(mask, false));
    // chosen, the mask goes into its layer; with none left, Mask is back
    assert!(s.merge_mask(bottom));
    assert!(s.layers().iter().all(|l| l.kind != LayerType::Mask));
    assert!(options(bottom).contains(&O::Mask) && !options(bottom).contains(&O::MergeMask));
    assert!(!s.merge_mask(bottom));
    // a text layer: its own two before Reference, nothing that would paint into it
    assert!(s.set_layer_locked(top, false) && s.select_layer(top));
    let text = s.text_begin(None, text_info("Hi")).unwrap();
    assert_eq!(
        options(text),
        [
            O::Rename,
            O::Select,
            O::Copy,
            O::Mask,
            O::ClippingMask,
            O::EditText,
            O::Rasterize,
            O::Reference,
            O::MergeDown,
            O::CombineDown
        ]
    );
    assert!(s.layer_options(9999).is_empty());
}

#[test]
fn an_edit_to_part_of_a_layer_keeps_only_that_part_to_undo() {
    use crate::selection::SelectionJoin;
    let Some(s) = session(400, 400) else { return };
    let history = |s: &CanvasSession| {
        let _ = pixel(s, 0, 0);
        s.shared.lock().canvas.as_ref().map_or(0, |c| c.history_bytes())
    };
    let part = 42 * 22 * 4;
    // a 40 x 20 selection filled with red: the step keeps that much, not the whole layer
    s.select_shape(false, 100.0, 100.0, 140.0, 120.0, SelectionJoin::Add);
    s.set_color(1.0, 0.0, 0.0);
    let before = history(&s);
    s.fill_selection();
    let kept = history(&s) - before;
    assert!(kept > 0 && kept <= part, "{kept}");
    assert_eq!(pixel(&s, 120, 110), [255, 0, 0, 255]);
    assert_eq!(pixel(&s, 150, 110), [255, 255, 255, 255]);
    // inverted: only what is painted changes
    let id = s.layers()[0].id;
    s.select_none();
    let before = history(&s);
    assert!(s.invert_layer(id));
    let kept = history(&s) - before;
    assert!(kept > 0 && kept <= part, "{kept}");
    assert_eq!(pixel(&s, 120, 110), [0, 255, 255, 255]);
    // undone and redone as before
    s.undo();
    assert_eq!(pixel(&s, 120, 110), [255, 0, 0, 255]);
    s.undo();
    s.undo();
    assert_eq!(pixel(&s, 120, 110), [255, 255, 255, 255]);
    s.redo();
    assert_eq!(pixel(&s, 120, 110), [255, 0, 0, 255]);
    assert_eq!(pixel(&s, 150, 110), [255, 255, 255, 255]);
    // a clear layer has nothing to invert
    let empty = s.add_layer();
    assert!(!s.invert_layer(empty));
}

#[test]
fn a_layers_own_actions() {
    let Some(s) = session(100, 100) else { return };
    s.set_brush_size(0.4);
    s.set_color(1.0, 0.0, 0.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(30.0, 30.0, 0.0)]);
    s.stroke_end(vec![]);
    let id = s.layers()[0].id;
    // invert: red to cyan, the coverage kept
    assert!(s.invert_layer(id));
    assert_eq!(pixel(&s, 30, 30), [0, 255, 255, 255]);
    s.undo();
    // select what is on it
    assert!(s.select_layer_contents(id));
    assert!(s.has_selection());
    // fill within that selection with blue
    s.set_color(0.0, 0.0, 1.0);
    assert!(s.fill_layer(id));
    assert_eq!(pixel(&s, 30, 30), [0, 0, 255, 255]);
    assert_eq!(pixel(&s, 80, 80), [255, 255, 255, 255]);
    s.select_none();
    assert!(s.fill_layer(id));
    assert_eq!(pixel(&s, 80, 80), [0, 0, 255, 255]);
    assert_eq!(s.copy_layer_contents(id).unwrap().rgba.len(), 100 * 100 * 4);
    assert!(s.copy_layer_contents(id).unwrap().rgba.chunks(4).all(|p| p == [0, 0, 255, 255]));
    // undone, the layer as the fill within the selection left it; redone, all of it again
    s.undo();
    assert_eq!(pixel(&s, 80, 80), [255, 255, 255, 255]);
    assert_eq!(pixel(&s, 30, 30), [0, 0, 255, 255]);
    s.redo();
    assert_eq!(pixel(&s, 80, 80), [0, 0, 255, 255]);
    // one reference layer at a time
    let other = s.add_layer();
    assert!(s.set_layer_reference(id, true));
    assert!(s.set_layer_reference(other, true));
    let refs: Vec<bool> = s.layers().iter().map(|l| l.reference).collect();
    assert_eq!(refs.iter().filter(|&&r| r).count(), 1);
    assert!(s.layers().iter().any(|l| l.id == other && l.reference));
}

#[test]
fn masks_hide_and_groups_composite_together() {
    use crate::layers::LayerType;
    let Some(s) = session(100, 100) else { return };
    s.set_brush_size(0.6);
    s.set_color(1.0, 0.0, 0.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(50.0, 50.0, 0.0)]);
    s.stroke_end(vec![]);
    let red = s.layers()[0].id;
    // a white mask shows everything; black painted on it hides the layer there
    let mask = s.add_mask(red).unwrap();
    assert_eq!(pixel(&s, 50, 50), [255, 0, 0, 255]);
    s.set_color(0.0, 0.0, 0.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(50.0, 50.0, 0.0)]);
    s.stroke_end(vec![]);
    assert_eq!(pixel(&s, 50, 50), [255, 255, 255, 255]);
    let list = s.layers();
    assert_eq!(list.iter().find(|l| l.id == mask).map(|l| (l.kind, l.parent)), Some((LayerType::Mask, Some(red))));
    s.undo();
    assert_eq!(pixel(&s, 50, 50), [255, 0, 0, 255]);
    // a blue layer above, combined down with the red one: a group at half opacity shows both
    // composited first, then halved
    let blue = s.add_layer();
    s.set_color(0.0, 0.0, 1.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(20.0, 20.0, 0.0)]);
    s.stroke_end(vec![]);
    let group = s.combine_down(blue).unwrap();
    assert!(s.layers().iter().any(|l| l.id == group && l.kind == LayerType::Group));
    assert!(s.layers().iter().filter(|l| l.parent == Some(group)).count() >= 2);
    s.set_layer_opacity(group, 0.5, true);
    let [r, g, b, _] = pixel(&s, 50, 50);
    assert!(r == 255 && (125..=130).contains(&g) && (125..=130).contains(&b), "{:?}", [r, g, b]);
    let [r, g, b, _] = pixel(&s, 20, 20);
    assert!((125..=130).contains(&r) && b == 255 && (125..=130).contains(&g), "{:?}", [r, g, b]);
    // hidden, the group hides all of it
    s.set_layer_visible(group, false);
    assert_eq!(pixel(&s, 50, 50), [255, 255, 255, 255]);
    s.set_layer_visible(group, true);
    // a group takes no paint
    s.select_layer(group);
    s.stroke_begin(PointerKind::Finger, vec![sample(80.0, 80.0, 0.0)]);
    s.stroke_end(vec![]);
    assert_eq!(pixel(&s, 80, 80), [255, 255, 255, 255]);
    assert!(s.set_group_collapsed(group, true));
    assert!(s.layers().iter().any(|l| l.id == group && l.collapsed));
}

#[test]
fn groups_nest_flatten_and_merge_down() {
    let Some(s) = session(100, 100) else { return };
    let dot = |x: f32, y: f32, rgb: [f32; 3]| {
        s.set_color(rgb[0], rgb[1], rgb[2]);
        s.stroke_begin(PointerKind::Finger, vec![sample(x, y, 0.0)]);
        s.stroke_end(vec![]);
    };
    s.set_brush_size(0.6);
    dot(30.0, 30.0, [1.0, 0.0, 0.0]);
    let red = s.layers()[0].id;
    let blue = s.add_layer();
    dot(70.0, 70.0, [0.0, 0.0, 1.0]);
    let green = s.add_layer();
    dot(50.0, 50.0, [0.0, 1.0, 0.0]);
    // green and blue in a group above red, then a group in the group
    let outer = s.combine_down(green).unwrap();
    let inner = s.combine_down(green).unwrap();
    let info = |id: u64| s.layers().into_iter().find(|l| l.id == id).unwrap();
    assert_eq!((info(green).depth, info(inner).depth, info(outer).depth), (2, 1, 0));
    assert!(info(outer).can_merge && info(outer).can_combine && !info(outer).can_clip);
    assert!(!info(blue).can_merge && !info(blue).can_combine && info(green).can_clip);
    // the inner group at half opacity: its layers composited first, then halved
    s.set_layer_opacity(inner, 0.5, true);
    let near = |p: [u8; 4], q: [u8; 3]| (0..3).all(|i| p[i].abs_diff(q[i]) <= 2);
    assert!(near(pixel(&s, 50, 50), [128, 255, 128]), "{:?}", pixel(&s, 50, 50));
    assert!(near(pixel(&s, 70, 70), [128, 128, 255]), "{:?}", pixel(&s, 70, 70));
    assert_eq!(pixel(&s, 30, 30), [255, 0, 0, 255]);
    // flattened, it looks the same: one layer named after its bottom one, at the group's opacity
    let flat = s.flatten_group(inner).unwrap();
    assert!(near(pixel(&s, 50, 50), [128, 255, 128]), "{:?}", pixel(&s, 50, 50));
    assert!(near(pixel(&s, 70, 70), [128, 128, 255]));
    assert_eq!((info(flat).name.as_str(), info(flat).opacity, info(flat).parent), ("Layer 2", 0.5, Some(outer)));
    s.undo();
    assert!(s.layers().iter().any(|l| l.id == inner));
    s.redo();
    assert!(s.layers().iter().all(|l| l.id != inner));
    // the outer group's Merge Down takes its top layer into red, under it outside the group: the
    // group stays, empty, and it all looks the same
    assert!(s.merge_down(outer));
    assert_eq!(s.layers().iter().map(|l| l.id).collect::<Vec<_>>(), [outer, red]);
    assert!(near(pixel(&s, 50, 50), [128, 255, 128]), "{:?}", pixel(&s, 50, 50));
    assert_eq!(pixel(&s, 30, 30), [255, 0, 0, 255]);
    s.undo();
    assert!(s.layers().iter().any(|l| l.id == flat));
    // ungrouped, its layers come out
    assert!(s.ungroup(outer));
    assert!(s.layers().iter().all(|l| l.depth == 0));
    // a duplicate keeps the layer's mask
    let mask = s.add_mask(red).unwrap();
    let copy = s.duplicate_layer(red).unwrap();
    assert!(s.layers().iter().any(|l| l.parent == Some(copy) && l.id != mask));
}

#[test]
fn brushes_and_sets_are_made_copied_and_deleted() {
    let Some(s) = session(100, 100) else { return };
    let names = |set: usize| s.brush_library()[set].brushes.iter().map(|b| b.name.clone()).collect::<Vec<_>>();
    let start = s.current_brush();
    let set_name = s.brush_library()[start.set as usize].name.clone();
    let first = names(start.set as usize);
    // a copy goes just above, numbered ("Yarra" gives "Yarra 2"); the tool keeps its brush, now
    // one down
    let name = first[start.index as usize].clone();
    assert_eq!(s.duplicate_brush(start.set, start.index), Some(start.index));
    assert_eq!(names(start.set as usize).len(), first.len() + 1);
    assert_eq!(s.current_brush().index, start.index + 1);
    assert_eq!(names(start.set as usize)[start.index as usize], format!("{name} 2"));
    assert_eq!(s.current_brush().name, name);
    // the copy is edited, and the original deleted: the copy stays current
    assert!(s.select_brush(start.set, start.index));
    s.studio_begin();
    s.set_studio_setting("spacing".to_owned(), 0.4);
    s.studio_end(true);
    assert!(s.delete_brush(start.set, start.index + 1));
    assert_eq!((s.current_brush().index, names(start.set as usize).len()), (start.index, first.len()));
    // a new brush at the top of the set is chosen; deleting the current brush moves the tool to
    // the one in its place
    assert_eq!(s.new_brush(start.set), Some(0));
    assert_eq!((s.current_brush().index, s.current_brush().name.as_str()), (0, "Untitled Brush"));
    assert!(s.delete_brush(start.set, 0));
    assert_eq!(s.current_brush().name, first[0]);
    assert_eq!(s.new_brush(start.set), Some(0));
    // a new set at the top of the library moves the others down
    let sets = s.brush_library().len();
    assert_eq!(s.new_brush_set(), 0);
    assert_eq!(s.brush_library().len(), sets + 1);
    assert_eq!(s.current_brush().set, start.set + 1);
    assert!(s.rename_brush_set(0, " Mine ".to_owned()) && !s.rename_brush_set(0, "  ".to_owned()));
    assert_eq!(s.brush_library()[0].name, "Mine");
    // everything carries to another session
    let kept = s.saved_brush_library();
    let Some(other) = session(100, 100) else { return };
    assert!(other.load_brush_library(kept));
    let lib = other.brush_library();
    assert_eq!(lib.len(), sets + 1);
    assert_eq!(lib[0].name, "Mine");
    assert_eq!(lib[start.set as usize + 1].brushes[0].name, "Untitled Brush");
    assert!(other.select_brush(start.set + 1, start.index + 1));
    other.studio_begin();
    assert_eq!(other.studio_settings(vec!["spacing".to_owned()]), vec![0.4]);
    other.studio_end(false);
    // a brush shared as a file comes in at the top of a set, edits and all
    let file = s.brush_file(start.set + 1, start.index + 1).unwrap();
    assert_eq!(other.import_brush_file(0, file), Some(0));
    assert!(other.select_brush(0, 0));
    other.studio_begin();
    assert_eq!(other.studio_settings(vec!["spacing".to_owned()]), vec![0.4]);
    other.studio_end(false);
    assert_eq!(other.import_brush_file(0, "{}".to_owned()), None);
    // a set shared as a file comes in at the top of the library; a copy goes just above
    let file = s.brush_set_file(start.set + 1).unwrap();
    let count = other.brush_library().len();
    assert_eq!(other.import_brush_file(3, file), Some(0));
    assert_eq!(other.brush_library().len(), count + 1);
    assert_eq!(other.brush_library()[0].brushes.len(), s.brush_library()[start.set as usize + 1].brushes.len());
    assert_eq!(other.duplicate_brush_set(0), Some(0));
    assert_eq!(other.brush_library()[1].name, other.brush_library()[0].name);
    // deleting a set takes its brushes; the only one goes too, leaving none
    assert!(s.delete_brush_set(start.set + 1));
    assert!(s.brush_library().iter().all(|set| set.name != set_name));
    while !s.brush_library().is_empty() {
        assert!(s.delete_brush_set(0));
    }
    assert!(!s.delete_brush_set(0));
    assert!(s.recent_brushes().is_empty());
    // a tool still draws with something
    s.stroke_begin(PointerKind::Finger, vec![sample(50.0, 50.0, 0.0)]);
    s.stroke_end(vec![]);
    // and a set made then holds the next brush
    assert_eq!(s.new_brush_set(), 0);
    assert_eq!(s.new_brush(0), Some(0));
    assert_eq!((s.current_brush().set, s.current_brush().index), (0, 0));
}

/// The library in use left with no sets is kept so, the first library too: it comes back empty,
/// not as the library the app ships.
#[test]
fn a_library_whose_last_set_was_deleted_comes_back_empty() {
    let dir = std::env::temp_dir().join(format!("procraft-empty-library-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    let path = dir.to_string_lossy().into_owned();
    let s = CanvasSession::new(32, 32);
    s.open_brushes(path.clone());
    assert!(!s.brush_library().is_empty());
    while !s.brush_library().is_empty() {
        assert!(s.delete_brush_set(0));
    }
    assert!(s.keep_brushes(path.clone()));
    let back = CanvasSession::new(32, 32);
    assert!(back.open_brushes(path.clone()));
    assert!(back.brush_library().is_empty());
    // read ahead too, as the gallery does
    crate::prepare_brushes(path);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn exports_psd_tiff_pdf_and_layer_pngs() {
    let Some(s) = session(40, 30) else { return };
    s.set_brush_size(0.6);
    s.set_color(1.0, 0.0, 0.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(20.0, 15.0, 0.0)]);
    s.stroke_end(vec![]);
    let top = s.add_layer();
    s.set_color(0.0, 0.0, 1.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(10.0, 10.0, 0.0)]);
    s.stroke_end(vec![]);
    s.combine_down(top).unwrap();
    s.add_mask(top).unwrap();
    let dir = std::env::temp_dir().join(format!("procraft-export-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = |name: &str| dir.join(name).to_string_lossy().into_owned();
    s.export_psd(path("a.psd")).unwrap();
    let psd = std::fs::read(dir.join("a.psd")).unwrap();
    assert_eq!(&psd[..4], b"8BPS");
    // a group's end marker, the background, and the mask (channel -2) are there
    assert!(psd.windows(14).any(|w| w == b"</Layer group>") && psd.windows(10).any(|w| w == b"Background"));
    assert!(psd.windows(2).any(|w| w == [0xFF, 0xFE]));
    s.export_tiff(path("a.tif")).unwrap();
    assert_eq!(&std::fs::read(dir.join("a.tif")).unwrap()[..4], b"II*\0");
    s.export_pdf(path("a.pdf"), true, 100).unwrap();
    let pdf = String::from_utf8_lossy(&std::fs::read(dir.join("a.pdf")).unwrap()).into_owned();
    assert!(pdf.contains("/Count 2"));
    s.export_pdf(path("b.pdf"), false, 60).unwrap();
    let pngs = s.export_layer_pngs(path("pngs")).unwrap();
    assert_eq!(pngs.len(), 2);
    assert!(pngs.iter().all(|p| std::path::Path::new(p).exists()));
    std::fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn artworks_go_into_one_pdf_a_page_each_at_their_own_sizes() {
    // a wide canvas and a tall one
    let made = |w: u32, h: u32| {
        let gpu = Gpu::headless().ok()?;
        let s = CanvasSession::new(w, h);
        {
            let mut st = s.shared.lock();
            st.gpu = Some(gpu);
            st.ensure_canvas();
        }
        Some(s)
    };
    let (Some(wide), Some(tall)) = (made(40, 30), made(20, 50)) else { return };
    let dir = std::env::temp_dir().join(format!("procraft-book-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("both.pdf");
    let book = crate::PdfBook::create(path.to_string_lossy().into_owned(), 100).unwrap();
    book.add(wide.clone()).unwrap();
    book.add(tall.clone()).unwrap();
    assert_eq!(book.pages(), 2);
    // nothing in its place until it is finished
    assert!(!path.exists());
    book.finish().unwrap();
    assert!(book.add(wide.clone()).is_err() && book.finish().is_err());
    let pdf = String::from_utf8_lossy(&std::fs::read(&path).unwrap()).into_owned();
    assert!(pdf.contains("/Count 2"));
    // the pages in the order added, each its canvas's size at its resolution
    let size = |s: &CanvasSession, w: f32, h: f32| {
        let dpi = s.info().dpi;
        format!("/MediaBox [0 0 {:.2} {:.2}]", w * 72.0 / dpi, h * 72.0 / dpi)
    };
    let (first, second) = (size(&wide, 40.0, 30.0), size(&tall, 20.0, 50.0));
    let (a, b) = (pdf.find(&first).unwrap(), pdf.find(&second).unwrap());
    assert!(a < b, "{first} {second}");
    // one left unfinished leaves nothing
    let other = crate::PdfBook::create(dir.join("other.pdf").to_string_lossy().into_owned(), 60).unwrap();
    other.add(tall).unwrap();
    drop(other);
    let left: Vec<_> = std::fs::read_dir(&dir).unwrap().map(|e| e.unwrap().file_name()).collect();
    assert_eq!(left, [std::ffi::OsString::from("both.pdf")]);
    std::fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn fit_to_canvas_keeps_a_flip_and_a_turn() {
    use crate::transform::TransformAction;
    let Some(s) = session(100, 100) else { return };
    no_streamline(&s);
    s.set_brush_size(0.2);
    // red on the left, blue on the right of a box wider than tall
    s.set_color(1.0, 0.0, 0.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(30.0, 50.0, 0.0)]);
    s.stroke_end(vec![]);
    s.set_color(0.0, 0.0, 1.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(60.0, 50.0, 0.0)]);
    s.stroke_end(vec![]);
    // the x of the reddest and the bluest pixel along the row through the middle
    let row = |s: &CanvasSession, y: u32| {
        let px: Vec<[u8; 4]> = (0..100).map(|x| pixel(s, x, y)).collect();
        let most = |c: usize| {
            (0..100u32).max_by_key(|&x| i32::from(px[x as usize][c]) - i32::from(px[x as usize][1])).unwrap()
        };
        (most(0), most(2))
    };
    let (red, blue) = row(&s, 50);
    assert!(red < blue, "{red} {blue}");
    s.transform_begin().unwrap();
    s.transform_apply(TransformAction::FlipHorizontal);
    let fitted = s.transform_apply(TransformAction::FitToCanvas).unwrap();
    // as wide as the canvas
    let xs: Vec<f32> = fitted.corners.iter().step_by(2).copied().collect();
    let (left, right) = (xs.iter().copied().fold(f32::MAX, f32::min), xs.iter().copied().fold(f32::MIN, f32::max));
    assert!(left.abs() < 0.5 && (right - 100.0).abs() < 0.5, "{xs:?}");
    s.transform_end(true);
    // flipped still: red on the right now
    let (red, blue) = row(&s, 50);
    assert!(red > blue, "{red} {blue}");
    // a quarter turn fitted: red and blue one above the other, the box as tall as the canvas
    s.transform_begin().unwrap();
    s.transform_apply(TransformAction::Rotate45);
    s.transform_apply(TransformAction::Rotate45);
    let fitted = s.transform_apply(TransformAction::FitToCanvas).unwrap();
    let ys: Vec<f32> = fitted.corners.iter().skip(1).step_by(2).copied().collect();
    let (top, bottom) = (ys.iter().copied().fold(f32::MAX, f32::min), ys.iter().copied().fold(f32::MIN, f32::max));
    assert!(top.abs() < 0.5 && (bottom - 100.0).abs() < 0.5, "{ys:?}");
    s.transform_end(true);
    let column: Vec<[u8; 4]> = (0..100).map(|y| pixel(&s, 50, y)).collect();
    let most = |c: usize| (0..100usize).max_by_key(|&y| i32::from(column[y][c]) - i32::from(column[y][1])).unwrap();
    // turned clockwise, what was on the right (red, after the flip) is at the bottom
    assert!(most(0) > most(2), "{} {}", most(0), most(2));
}

#[test]
fn text_is_edited_as_one_step_and_rasterized() {
    use crate::text::{TextAlignment, TextInfo};
    let Some(s) = session(40, 40) else { return };
    let info = TextInfo {
        text: "Hi".to_owned(),
        font: "sans-serif".to_owned(),
        style: "Regular".to_owned(),
        size: 20.0,
        kerning: 0.0,
        tracking: 0.0,
        leading: 0.0,
        baseline: 0.0,
        opacity: 1.0,
        align: TextAlignment::Left,
        underline: false,
        outline: false,
        vertical: false,
        all_caps: false,
        r: 1.0,
        g: 0.0,
        b: 0.0,
        x: 2.0,
        y: 2.0,
        width: 0.0,
        runs: Vec::new(),
    };
    let red = [255u8, 0, 0, 255].repeat(40 * 40);
    let id = s.text_begin(None, info.clone()).unwrap();
    assert_eq!(s.editing_text(), Some(id));
    s.put_text_pixels(red.clone());
    assert!(s.set_text(TextInfo { text: "Hello".to_owned(), ..info.clone() }).is_some());
    s.put_text_pixels(red.clone());
    assert_eq!(pixel(&s, 5, 5), [255, 0, 0, 255]);
    s.text_end(true);
    let layer = s.layers().into_iter().find(|l| l.id == id).unwrap();
    assert!(layer.text && layer.name == "Hello");
    assert_eq!(s.layer_text(id).unwrap().text, "Hello");
    // a text layer takes no paint
    s.set_color(0.0, 0.0, 1.0);
    s.stroke_begin(PointerKind::Finger, vec![sample(5.0, 5.0, 0.0)]);
    s.stroke_end(vec![]);
    assert_eq!(pixel(&s, 5, 5), [255, 0, 0, 255]);
    // the step undo would undo next is that text's, so the app edits it again first
    assert_eq!(s.text_undo_layer(), Some(id));
    // edited again without a change, ending it makes no step: the text step is still next
    assert_eq!(s.text_begin(Some(id), s.layer_text(id).unwrap()), Some(id));
    assert_eq!(s.text_undo_layer(), None);
    s.text_end(true);
    assert_eq!(s.text_undo_layer(), Some(id));
    // one undo takes the new text layer away; redo brings it back, to edit again
    s.undo();
    assert_eq!(s.text_redo_layer(), Some(id));
    assert_eq!((s.layers().len(), pixel(&s, 5, 5)), (1, [255, 255, 255, 255]));
    s.redo();
    assert_eq!(s.layer_text(id).unwrap().text, "Hello");
    assert_eq!(pixel(&s, 5, 5), [255, 0, 0, 255]);
    // edited again and cancelled, it is as it was
    assert_eq!(s.text_begin(Some(id), info.clone()), Some(id));
    s.set_text(TextInfo { text: "Changed".to_owned(), ..info.clone() });
    s.put_text_pixels([0u8, 255, 0, 255].repeat(40 * 40));
    s.text_end(false);
    assert_eq!(s.layer_text(id).unwrap().text, "Hello");
    assert_eq!(pixel(&s, 5, 5), [255, 0, 0, 255]);
    // new text left empty goes away
    let count = s.layers().len();
    s.text_begin(None, TextInfo { text: String::new(), ..info.clone() }).unwrap();
    s.text_end(true);
    assert_eq!(s.layers().len(), count);
    // rasterized, it takes paint
    assert!(s.rasterize_layer(id) && s.layer_text(id).is_none());
    assert!(s.select_layer(id));
    s.stroke_begin(PointerKind::Finger, vec![sample(5.0, 5.0, 0.0)]);
    s.stroke_end(vec![]);
    assert_ne!(pixel(&s, 5, 5), [255, 0, 0, 255]);
}

/// The Reference windows that show the canvas share one picture of it: read back from the GPU
/// once while the artwork stays as it is, however many windows ask, and again once it changes.
#[test]
fn the_reference_windows_read_the_canvas_once_while_it_stays_as_it_is() {
    let Some(s) = session(1024, 512) else { return };
    s.set_background_color(0.0, 0.0, 1.0, true);
    let t = std::time::Instant::now();
    let first = s.reference_canvas(700).unwrap();
    let read = t.elapsed();
    // the quickest of several asks, so a busy machine's pauses don't count against sharing
    let mut shared = std::time::Duration::MAX;
    for _ in 0..8 {
        let t = std::time::Instant::now();
        assert_eq!(s.reference_canvas(700).as_ref(), Some(&first));
        shared = shared.min(t.elapsed());
    }
    println!("the canvas read for the reference windows in {read:?}, shared again in {shared:?} at the quickest");
    assert!(shared < read, "{shared:?} shared, {read:?} read");
    assert_eq!((first.width, first.height, &first.rgba[..4]), (700, 700, &[0, 0, 255, 255][..]));
    // another size reads it again, and so does a change
    assert_eq!(s.reference_canvas(64).map(|t| t.width), Some(64));
    s.set_background_color(0.0, 1.0, 0.0, true);
    assert_eq!(s.reference_canvas(700).map(|t| t.rgba[..4].to_vec()), Some(vec![0, 255, 0, 255]));
}

